ON CONFLICT ("Id") DO UPDATE SET
    "Nombre" = EXCLUDED."Nombre",
    "NombrePlural" = EXCLUDED."NombrePlural",
    "CategoriaId" = EXCLUDED."CategoriaId",
    "Emoji" = EXCLUDED."Emoji",
    "UnidadDefaultId" = EXCLUDED."UnidadDefaultId",
    "PesoUnidadGr" = EXCLUDED."PesoUnidadGr",
    "TieneTamanio" = EXCLUDED."TieneTamanio",
    "EsBasico" = EXCLUDED."EsBasico",
    "Sinonimos" = EXCLUDED."Sinonimos",
    "BusquedaImagen" = EXCLUDED."BusquedaImagen",
    "ImagenUrl" = CASE
      WHEN EXCLUDED."ImagenUrl" IS NOT NULL THEN EXCLUDED."ImagenUrl"
      WHEN EXCLUDED."BusquedaImagen" = '-' THEN NULL
      ELSE "Ingredientes"."ImagenUrl" END,
    "EsPersonalizado" = false;

-- Los ingredientes tuyos que quedaron duplicados con la base pasan a contar como el de la base
UPDATE "Ingredientes" p SET "EquivaleAId" = b."Id"
FROM "Ingredientes" b
WHERE p."EsPersonalizado" = true AND b."EsPersonalizado" = false
  AND p."EquivaleAId" IS NULL AND lower(p."Nombre") = lower(b."Nombre") || ' (mío)';

-- 6) Recetas base (las recetas creadas desde la app no se tocan)
DELETE FROM "RecetaPasos" WHERE "RecetaId" IN (SELECT "Id" FROM "Recetas" WHERE "EsPersonalizada" = false);
DELETE FROM "RecetaIngredientes" WHERE "RecetaId" IN (SELECT "Id" FROM "Recetas" WHERE "EsPersonalizada" = false);

INSERT INTO "Recetas" ("Id", "Nombre", "Descripcion", "Categoria", "TiempoMin", "Dificultad", "Porciones", "Emoji", "Consejo", "BusquedaImagen", "EsPersonalizada") VALUES
  (1, 'Milanesas con puré de papas', 'El clásico de todas las casas: milanesas doradas al horno con un puré bien cremoso.', 'Carnes', 60, 'Fácil', 4, '🍽️', 'Si las freís, el aceite está listo cuando tirás una miga de pan y burbujea enseguida (unos 170 °C).', 'Milanesa', false),
  (2, 'Milanesa a la napolitana', 'Milanesa con salsa de tomate, jamón y muzzarella gratinada. Un clásico de bodegón.', 'Carnes', 50, 'Fácil', 4, '🍕', 'Cociná la milanesa primero y recién después agregale la cobertura: si va cruda con la salsa, el empanado se humedece.', 'Milanesa a la napolitana', false),
  (3, 'Empanadas de carne al horno', 'Jugosas, con cebolla, huevo duro y aceituna, como se hacen en cada provincia.', 'Tartas y empanadas', 90, 'Media', 4, '🥟', 'El relleno tiene que estar frío antes de armar: si está caliente, la masa se rompe y las empanadas se abren en el horno.', 'Empanada argentina', false),
  (4, 'Tarta de jamón y queso', 'Rápida, rendidora y siempre bienvenida. Ideal para una cena sin vueltas.', 'Tartas y empanadas', 50, 'Fácil', 4, '🥧', 'Pinchá la masa de abajo con un tenedor antes de rellenar para que no se infle y quede crocante.', 'Quiche', false),
  (5, 'Tarta de acelga', 'La tarta de verdura de siempre, con queso y un toque de nuez moscada.', 'Tartas y empanadas', 60, 'Fácil', 4, '🥬', 'Escurrí muy bien la acelga cocida apretándola con las manos: el exceso de agua es lo que arruina una tarta de verdura.', 'Tarta de acelga', false),
  (6, 'Pascualina de espinaca', 'Tarta de espinaca y ricota con huevos enteros escondidos adentro.', 'Tartas y empanadas', 70, 'Media', 6, '🥚', 'Hacé los huecos para los huevos con el dorso de una cuchara; así quedan enteros y se ven al cortar.', 'Torta pascualina', false),
  (7, 'Guiso de lentejas', 'Bien argentino, con chorizo, panceta y verduras. Ideal para los días fríos.', 'Guisos y sopas', 75, 'Fácil', 6, '🍲', 'Como todo guiso, es más rico al día siguiente: los sabores se asientan.', 'Guiso de lentejas', false),
  (8, 'Locro criollo', 'El plato patrio: maíz, porotos, zapallo y carnes, cocinado despacio, con su salsita picante.', 'Guisos y sopas', 210, 'Media', 8, '🇦🇷', 'Revolvé seguido con cuchara de madera y raspá el fondo: el locro se pega fácil.', 'Locro', false),
  (9, 'Carbonada criolla', 'Guiso de carne con zapallo, choclo, batata y duraznos que le dan un toque dulce.', 'Guisos y sopas', 90, 'Media', 6, '🎃', 'Tradicionalmente se sirve dentro de un zapallo horneado. Si querés lucirte, probalo.', 'Carbonada', false),
  (10, 'Pastel de papa', 'Carne picada bien condimentada debajo de un colchón de puré gratinado.', 'Carnes', 70, 'Fácil', 6, '🥔', 'Espolvoreá un poco de azúcar sobre el puré antes de gratinar: queda una costra dorada típica de los bodegones.', 'Pastel de papa', false),
  (11, 'Tortilla de papas', 'Jugosa por dentro y dorada por fuera. Con o sin cebolla, según la grieta de cada casa.', 'Minutas', 45, 'Media', 4, '🍳', 'Para darla vuelta, apoyá un plato más grande que la sartén encima, invertí con un movimiento firme y deslizala de nuevo.', 'Tortilla de patatas', false),
  (12, 'Revuelto gramajo', 'Papas pay, huevo y jamón revueltos en sartén. Una minuta porteña de pura cepa.', 'Minutas', 30, 'Fácil', 2, '🍳', 'Sacalo del fuego cuando el huevo todavía esté un poco húmedo: termina de cocinarse con el calor residual.', 'Revuelto gramajo', false),
  (13, 'Fideos con tuco', 'La salsa de tomate de la abuela, cocinada despacio, sobre unos buenos fideos.', 'Pastas', 45, 'Fácil', 4, '🍝', 'Una pizca de azúcar corrige la acidez del tomate. Y guardá un poco del agua de cocción por si la salsa queda espesa.', 'Espaguetis con salsa de tomate', false),
  (14, 'Ñoquis de papa', 'Caseros y livianos, como los del 29. Con tuco o con manteca y queso.', 'Pastas', 80, 'Media', 4, '🥔', 'Usá papas viejas o de cáscara colorada, que tienen menos agua, y no amases de más: con la harina justa quedan livianos.', 'Ñoquis', false),
  (15, 'Arroz con pollo', 'Todo en una olla: pollo dorado, verduras y arroz que absorbe todo el sabor.', 'Pollo', 60, 'Fácil', 4, '🍗', 'Una vez que agregás el caldo, no revuelvas el arroz: solo tapá y dejá que se cocine.', 'Arroz con pollo', false),
  (16, 'Pollo al horno con papas', 'Presas doradas con ajo y limón, sobre una cama de papas que se cocinan en el jugo.', 'Pollo', 75, 'Fácil', 4, '🍗', 'Dejá el pollo marinando aunque sea 30 minutos con el limón y el ajo: la diferencia se nota.', 'Pollo asado', false),
  (17, 'Supremas de pollo empanadas', 'Pechuga de pollo crocante por fuera y tierna por dentro. Más liviana que la milanesa de carne.', 'Pollo', 40, 'Fácil', 4, '🍗', 'Abrí las pechugas en mariposa y aplastalas: si quedan gruesas, se secan por fuera antes de cocinarse por dentro.', 'Milanesa de pollo', false),
  (18, 'Matambre a la pizza', 'Matambre tiernizado en leche y cubierto con salsa, muzzarella y orégano.', 'Carnes', 120, 'Media', 4, '🍕', 'La cocción en leche es lo que lo deja tiernísimo; no te saltees ese paso.', 'Matambre a la pizza', false),
  (19, 'Bifes a la criolla', 'Bifes cocidos en capas con papa, cebolla, morrón y tomate, en su propio jugo.', 'Carnes', 60, 'Fácil', 4, '🥩', 'No revuelvas: la gracia es que cada capa se cocine con el vapor y los jugos de la anterior.', 'Bife a la criolla', false),
  (20, 'Estofado de carne con papas', 'Carne tierna en salsa de tomate y vino, con papas que se deshacen en la boca.', 'Guisos y sopas', 120, 'Fácil', 6, '🍲', 'Pasá la carne por un poco de harina antes de dorarla: la salsa queda más espesa y untuosa.', 'Estofado', false),
  (21, 'Albóndigas con salsa', 'Albóndigas caseras bien tiernas, cocinadas en salsa de tomate. Van con arroz, puré o fideos.', 'Carnes', 60, 'Fácil', 4, '🧆', 'Mojate las manos con agua para darles forma: así no se pegan y quedan lisas.', 'Albóndiga', false),
  (22, 'Hamburguesas caseras', 'Medallones jugosos de carne picada, a la plancha, en pan con lo que tengas.', 'Carnes', 30, 'Fácil', 4, '🍔', 'Hacé un hueco con el pulgar en el centro de cada medallón: así no se inflan al cocinarse y quedan planas.', 'Hamburguesa', false),
  (23, 'Choripán con salsa criolla', 'El sándwich de la cancha y del asado, con chorizo a la parrilla o a la plancha.', 'Carnes', 35, 'Fácil', 4, '🌭', 'Abrí los chorizos en mariposa: se cocinan más rápido y parejo.', 'Choripán', false),
  (24, 'Provoleta con tomates', 'Queso provolone dorado por fuera y fundido por dentro, con orégano y ají.', 'Vegetariano', 20, 'Fácil', 2, '🧀', 'Metela 30 minutos al freezer antes de cocinarla: se dora por fuera sin desarmarse.', 'Provoleta', false),
  (25, 'Pizza casera de muzzarella', 'Masa casera esponjosa, salsa de tomate y mucha muzzarella. Estilo pizzería porteña.', 'Pizzas', 110, 'Media', 4, '🍕', 'Prehorneá la masa con la salsa antes de poner el queso: así la base queda cocida y el queso no se quema.', 'Pizza', false),
  (26, 'Fugazzeta rellena', 'Doble masa, muzzarella en el medio y una montaña de cebolla dorada arriba.', 'Pizzas', 120, 'Media', 4, '🧅', 'Cortá la cebolla bien fina y dejala con sal 15 minutos: larga agua y se dora mejor en el horno.', 'Fugazzeta', false),
  (27, 'Sopa de verduras', 'Reconfortante y liviana, para aprovechar las verduras que quedan en la heladera.', 'Guisos y sopas', 45, 'Fácil', 4, '🥣', 'Si la licuás al final, se transforma en una crema de verduras.', 'Sopa de verduras', false),
  (28, 'Puchero', 'Carne y verduras hervidas juntas: un caldo de primera y un plato abundante.', 'Guisos y sopas', 150, 'Fácil', 6, '🍖', 'Agregá las verduras según su dureza: primero las más duras (choclo, zanahoria), al final las más tiernas (zapallo).', 'Puchero', false),
  (29, 'Ensalada rusa', 'Papa, zanahoria, arvejas y huevo con mayonesa. Infaltable como acompañamiento.', 'Ensaladas', 40, 'Fácil', 4, '🥗', 'Cortá papa y zanahoria en cubitos antes de hervir: quedan parejos y se cocinan en la mitad de tiempo.', 'Ensalada rusa', false),
  (30, 'Ensalada mixta', 'Lechuga, tomate y cebolla: la ensalada de todos los días para acompañar cualquier plato.', 'Ensaladas', 10, 'Fácil', 2, '🥗', 'Condimentá justo antes de servir para que la lechuga no se marchite.', 'Ensalada mixta', false),
  (31, 'Zapallitos rellenos', 'Zapallitos gratinados rellenos con su pulpa, cebolla y queso. Con o sin carne.', 'Vegetariano', 55, 'Fácil', 4, '🟢', 'Para una versión más contundente, sumale al relleno carne picada salteada.', 'Zapallito relleno', false),
  (32, 'Budín de zapallitos', 'Una especie de tortilla al horno, esponjosa y liviana, ideal para la cena.', 'Vegetariano', 50, 'Fácil', 4, '🥒', 'También sale con zucchini o mezclando los dos.', 'Budín de zapallitos', false),
  (33, 'Polenta con tuco y queso', 'Polenta cremosa con manteca y queso, bañada en un tuco con o sin carne.', 'Vegetariano', 40, 'Fácil', 4, '🌽', 'Echá la polenta en lluvia batiendo con batidor para que no se formen grumos.', 'Polenta', false),
  (34, 'Guiso de arroz', 'Arroz cocinado en un caldo de tomate con carne y verduras. Rendidor y económico.', 'Guisos y sopas', 50, 'Fácil', 4, '🍚', 'Tiene que quedar caldoso: si se seca mucho, agregá agua caliente de a poco.', 'Guiso', false),
  (35, 'Fideos con manteca y queso', 'La solución más rápida cuando no hay nada. Simple, pero hecha bien es una caricia.', 'Pastas', 15, 'Fácil', 2, '🍝', 'Agregá un cucharón del agua de cocción con la manteca y el queso: se forma una salsa cremosa que se adhiere a los fideos.', 'Pasta al burro', false),
  (36, 'Fideos con crema, jamón y champiñones', 'Una salsa blanca rápida con jamón y hongos salteados.', 'Pastas', 25, 'Fácil', 4, '🍄', 'No dejes hervir la crema a fuego fuerte: con un hervor suave alcanza para que espese.', 'Pasta con champiñones', false),
  (37, 'Canelones de verdura', 'Panqueques rellenos de acelga y ricota, con salsa blanca y tuco gratinados.', 'Pastas', 90, 'Media', 4, '🌯', 'Podés usar espinaca en lugar de acelga, o mitad y mitad.', 'Canelones', false),
  (38, 'Humita en olla', 'Crema de choclo rallado con cebolla, morrón y zapallo. Plato norteño por excelencia.', 'Vegetariano', 50, 'Fácil', 4, '🌽', 'Rallá los choclos con el rallador grueso sobre un bowl para aprovechar toda la leche del grano.', 'Humita', false),
  (39, 'Guiso de garbanzos', 'Garbanzos con chorizo, tomate y pimentón. Simple, sabroso y lleno de proteína.', 'Guisos y sopas', 70, 'Fácil', 4, '🫘', 'Si usás garbanzos secos, remojalos la noche anterior. Los de frasco se suman al final y se cocinan 10 minutos.', 'Potaje de garbanzos', false),
  (40, 'Buñuelos de acelga', 'Bocados fritos, crocantes por fuera y tiernos por dentro. Buena forma de que todos coman verdura.', 'Vegetariano', 35, 'Fácil', 4, '🥬', 'Freílos con el aceite a temperatura media: si está muy caliente se doran afuera y quedan crudos adentro.', 'Buñuelo', false),
  (41, 'Bife a caballo con papas fritas', 'Bife jugoso con huevo frito encima y papas fritas caseras. Minuta de bodegón.', 'Minutas', 35, 'Fácil', 2, '🍳', 'Secá bien los bastones de papa antes de freír para que queden crocantes.', 'Bife a caballo', false),
  (42, 'Pan de carne relleno', 'Arrollado de carne picada relleno de jamón y queso, horneado hasta dorar.', 'Carnes', 70, 'Media', 6, '🍖', 'Arrollalo usando un papel manteca o film como base, igual que un arrollado dulce.', 'Pastel de carne', false),
  (43, 'Zapallo relleno gratinado', 'Medio zapallo asado y relleno de choclo cremoso con queso.', 'Vegetariano', 70, 'Fácil', 2, '🎃', 'Usá zapallo anco: es dulce y tiene la forma ideal para rellenar.', 'Cucurbita moschata', false),
  (44, 'Filet de merluza a la romana', 'Pescado rebozado en una masa liviana y crocante, con limón.', 'Pescados', 30, 'Fácil', 4, '🐟', 'Si la masa queda fría (podés usar agua con gas helada en lugar de leche) el rebozado sale más crocante.', 'Merluccius hubbsi', false),
  (45, 'Ensalada de arroz con atún', 'Plato frío completo para los días de calor: arroz, atún, huevo y verduras.', 'Ensaladas', 30, 'Fácil', 4, '🥗', 'Enjuagá el arroz cocido con agua fría para cortar la cocción y que los granos queden sueltos.', 'Ensalada de arroz', false),
  (46, 'Pollo al verdeo', 'Pechuga en cubos con una salsa de crema y cebolla de verdeo. Va con arroz o puré.', 'Pollo', 30, 'Fácil', 4, '🌱', 'Separá la parte blanca del verdeo (para rehogar) de la verde (para el final): así conservás el color y el sabor fresco.', 'Pollo al verdeo', false),
  (47, 'Revuelto de zapallitos', 'Zapallitos salteados con cebolla y huevo. Listo en 20 minutos.', 'Vegetariano', 20, 'Fácil', 2, '🥚', 'Cortá los zapallitos en cubitos chicos para que se doren y no larguen tanta agua.', 'Revuelto', false),
  (48, 'Guiso de fideos', 'Mostacholes o tirabuzones cocinados en un caldo espeso de tomate y carne.', 'Guisos y sopas', 50, 'Fácil', 4, '🍲', 'Usá fideos cortos y gruesos, que aguantan la cocción en el guiso sin pasarse.', 'Guiso de fideos', false),
  (49, 'Tarta de choclo', 'Relleno cremoso de choclo con salsa blanca y queso, dentro de una masa dorada.', 'Tartas y empanadas', 60, 'Fácil', 4, '🌽', 'Con choclo en lata sale igual de rica y te ahorrás el paso de desgranar.', 'Tarta de choclo', false),
  (50, 'Milanesas de berenjena', 'Rodajas de berenjena empanadas y horneadas. Se pueden hacer a la napolitana.', 'Vegetariano', 50, 'Fácil', 4, '🍆', 'Salá las rodajas y dejalas 20 minutos para que larguen el amargor; después secalas con papel.', 'Solanum melongena', false),
  (51, 'Pollo a la portuguesa', 'Presas de pollo cocinadas en una salsa de tomate, cebolla y morrones.', 'Pollo', 60, 'Fácil', 4, '🍅', 'Queda ideal con arroz blanco o papas al natural para mojar en la salsa.', 'Pollo guisado', false),
  (52, 'Hamburguesas de lentejas', 'Medallones vegetarianos de lentejas y verduras, dorados en sartén o al horno.', 'Vegetariano', 60, 'Media', 4, '🫘', 'Si la mezcla queda muy húmeda, sumá pan rallado de a cucharadas hasta poder formar los medallones.', 'Hamburguesa vegetariana', false),
  (53, 'Salpicón de pollo', 'Ensalada fría de pollo, papa, huevo y verduras. Una cena fresca de verano.', 'Ensaladas', 45, 'Fácil', 4, '🥗', 'Aprovechá el caldo de hervir el pollo para una sopa al día siguiente.', 'Salpicón', false),
  (54, 'Bife con puré de calabaza', 'Bife a la plancha con un puré de zapallo suave y dulzón. Cena rápida y completa.', 'Carnes', 35, 'Fácil', 2, '🥩', 'Dejá reposar el bife 3 minutos antes de cortarlo para que no pierda los jugos.', 'Puré de calabaza', false),
  (55, 'Tarta de zapallitos', 'Zapallitos rallados con cebolla, huevo y queso. Una tarta liviana y económica.', 'Tartas y empanadas', 60, 'Fácil', 4, '🥧', 'Hacela con una sola tapa y la superficie descubierta: se gratina el queso y queda muy linda.', 'Tarta de zapallitos', false),
  (56, 'Vacío al horno con papas', 'Vacío tierno y dorado, cocinado lento con papas que se impregnan de su jugo.', 'Carnes', 150, 'Fácil', 4, '🥩', 'Cocinalo con la grasa hacia arriba y tapado la primera parte: queda tierno por dentro y crocante por fuera.', 'Vacío (corte de carne)', false),
  (57, 'Asado de tira al horno', 'Para cuando no hay parrilla: tiras de asado jugosas y doradas en el horno de casa.', 'Carnes', 100, 'Fácil', 4, '🍖', 'Pedí el asado de tira finito (3 o 4 cm): se cocina parejo y queda más tierno en el horno.', 'Asado de tira', false),
  (58, 'Entraña con papas rústicas', 'Entraña a la plancha bien sellada con papas al horno con provenzal.', 'Carnes', 50, 'Fácil', 2, '🥩', 'La entraña se cocina rápido y a fuego fuerte: si se pasa, se pone dura.', 'Entraña', false),
  (59, 'Colita de cuadril al horno con verduras', 'Una pieza entera, jugosa, con calabaza, batata y cebolla asadas.', 'Carnes', 90, 'Fácil', 4, '🥩', 'Sellá la colita en una sartén antes de hornearla: concentra los jugos.', 'Colita de cuadril', false),
  (60, 'Lomo al champiñón', 'Medallones de lomo con una salsa cremosa de champiñones. Clásico de bodegón.', 'Carnes', 35, 'Media', 2, '🍄', 'Sellá los medallones a fuego muy fuerte y terminalos en la salsa solo un minuto, así quedan rosados.', 'Solomillo', false),
  (61, 'Bondiola a la cerveza', 'Bondiola de cerdo braseada en cerveza con cebollas, bien tierna y con salsa.', 'Carnes', 150, 'Fácil', 4, '🍺', 'Con unas ciruelas pasas en la salsa le das un toque dulce que combina muy bien con el cerdo.', 'Bondiola', false),
  (62, 'Bifes de cerdo con puré de manzana', 'Bifes de cerdo a la plancha con un puré de papa y manzana, dulce y salado.', 'Carnes', 40, 'Fácil', 4, '🍎', 'El cerdo se seca rápido: retiralo apenas pierda el color rosado en el centro.', 'Chuleta de cerdo', false),
  (63, 'Costillitas de cerdo a la barbacoa', 'Costillitas tiernas al horno, glaseadas con salsa barbacoa.', 'Carnes', 150, 'Fácil', 4, '🍖', 'Si no tenés salsa barbacoa, mezclá kétchup, miel, salsa de soja y pimentón.', 'Costillas de cerdo', false),
  (64, 'Matambrito de cerdo al limón', 'Matambrito tierno al horno con limón, ajo y papas.', 'Carnes', 90, 'Fácil', 3, '🍋', 'Marinalo con el limón al menos 30 minutos: ablanda la carne y le da mucho sabor.', 'Matambre', false),
  (65, 'Hígado encebollado con puré', 'Bifes de hígado tiernos con mucha cebolla dorada. Rico en hierro y muy económico.', 'Carnes', 40, 'Fácil', 4, '🧅', 'Remojá el hígado en leche 30 minutos antes de cocinarlo: le saca el gusto fuerte.', 'Hígado (alimento)', false),
  (66, 'Mondongo a la española', 'Mondongo tierno guisado con garbanzos, chorizo y pimentón.', 'Guisos y sopas', 180, 'Media', 6, '🍲', 'El secreto es hervir bien el mondongo antes: tiene que quedar muy tierno.', 'Mondongo', false),
  (67, 'Lengua a la vinagreta', 'Lengua hervida en fetas, con una vinagreta de morrón, cebolla y huevo. Se come fría.', 'Carnes', 180, 'Media', 6, '👅', 'Pelala en caliente, apenas sale de la olla: en frío la piel no sale.', 'Lengua (alimento)', false),
  (68, 'Cordero al horno con papas', 'Cordero patagónico al horno con romero, ajo y papas doradas.', 'Carnes', 150, 'Media', 4, '🐑', 'Pinchá la carne y metele dientes de ajo y ramitas de romero en los cortes.', 'Carne de cordero', false),
  (69, 'Pastel de choclo', 'Carne picada bien condimentada cubierta con una crema de choclo gratinada.', 'Carnes', 70, 'Media', 6, '🌽', 'Espolvoreá azúcar sobre la crema de choclo antes de gratinar para que se forme una costra dorada.', 'Pastel de choclo', false),
  (70, 'Sándwich de milanesa completo', 'El sánguche de milanesa con lechuga, tomate, jamón, queso y huevo.', 'Minutas', 40, 'Fácil', 2, '🥪', 'Tostá apenas el pan: aguanta mejor los jugos sin desarmarse.', 'Sándwich de milanesa', false),
  (71, 'Lomito completo', 'El clásico sándwich de lomo con jamón, queso, huevo, lechuga y tomate.', 'Minutas', 25, 'Fácil', 2, '🥪', 'Golpeá los bifes de lomo para que queden finitos y se cocinen en un minuto.', 'Lomito', false),
  (72, 'Panchos caseros', 'Salchichas en pan con los aderezos de siempre. La cena más rápida.', 'Minutas', 10, 'Fácil', 2, '🌭', 'Hervilas apenas: si el agua hierve fuerte, las salchichas se parten.', 'Pancho (comida)', false),
  (73, 'Morcipán', 'Morcilla a la plancha en pan crocante, con salsa criolla.', 'Minutas', 25, 'Fácil', 2, '🌭', 'Cocinala a fuego medio y sin pincharla, así no se abre.', 'Morcilla', false),
  (74, 'Salchichas con puré', 'Salchichas doradas con puré de papas. Simple, rápido y siempre bienvenido.', 'Minutas', 30, 'Fácil', 2, '🌭', 'Hacelas en sartén después de hervirlas para que queden doraditas.', 'Salchicha de Viena', false),
  (75, 'Chili con carne', 'Guiso picante de carne picada, porotos y tomate. Se sirve con arroz o tortillas.', 'Guisos y sopas', 60, 'Fácil', 4, '🌶️', 'Ajustá el picante a gusto: siempre se puede sumar, pero no sacar.', 'Chili con carne', false),
  (76, 'Burritos de carne y porotos', 'Tortillas rellenas de carne picada, porotos, arroz y queso.', 'Minutas', 40, 'Fácil', 4, '🌯', 'Calentá las tortillas antes de rellenarlas: se doblan sin romperse.', 'Burrito', false),
  (77, 'Empanadas de pollo', 'Jugosas empanadas de pollo con cebolla, morrón y verdeo.', 'Tartas y empanadas', 75, 'Media', 4, '🥟', 'Usá el caldo de hervir el pollo para humedecer un poco el relleno.', 'Empanada', false),
  (78, 'Empanadas de jamón y queso', 'Las más fáciles y rápidas: jamón y muzzarella que se derrite.', 'Tartas y empanadas', 30, 'Fácil', 4, '🧀', 'Cerralas bien para que el queso no se escape en el horno.', 'Empanada', false),
  (79, 'Empanadas de humita', 'Relleno cremoso de choclo con salsa blanca y queso. Infaltables en una docena.', 'Tartas y empanadas', 60, 'Media', 4, '🌽', 'El relleno tiene que quedar espeso y frío, si no las empanadas se abren.', 'Humita', false),
  (80, 'Empanadas árabes', 'Triangulares, con carne, tomate, cebolla y mucho limón.', 'Tartas y empanadas', 50, 'Media', 4, '🔺', 'El relleno va crudo: la carne se cocina en el horno y queda muy jugosa.', 'Sfiha', false),
  (81, 'Tarta de pollo', 'Pollo desmenuzado con cebolla, morrón y crema. Ideal para aprovechar pollo cocido.', 'Tartas y empanadas', 60, 'Fácil', 4, '🥧', 'Sirve para usar el pollo que sobró de otra comida.', 'Tarta', false),
  (82, 'Tarta de atún', 'Atún con cebolla, morrón, tomate y huevo. Una tarta rendidora con latas de la alacena.', 'Tartas y empanadas', 50, 'Fácil', 4, '🐟', 'Escurrí bien el atún para que la tarta no quede aguada.', 'Tarta', false),
  (83, 'Tarta de puerros', 'Puerros rehogados en manteca con crema y queso. Suave y elegante.', 'Tartas y empanadas', 55, 'Fácil', 4, '🥧', 'Lavá muy bien los puerros: entre las capas suele quedar tierra.', 'Quiche', false),
  (84, 'Tarta de calabaza y queso', 'Calabaza asada con cebolla y queso. Dulzona y muy rica.', 'Tartas y empanadas', 70, 'Fácil', 4, '🎃', 'Asá la calabaza en vez de hervirla: queda más sabrosa y con menos agua.', 'Cucurbita moschata', false),
  (85, 'Tarta de brócoli', 'Brócoli con queso y crema en una tarta abierta.', 'Tartas y empanadas', 50, 'Fácil', 4, '🥦', 'Cociná el brócoli apenas 3 minutos para que conserve el color.', 'Brócoli', false),
  (86, 'Pizza napolitana', 'Muzzarella, rodajas de tomate, ajo y orégano. Con prepizza sale en 20 minutos.', 'Pizzas', 25, 'Fácil', 2, '🍕', 'Rociá el ajo picado con aceite recién salida del horno: queda perfumado sin quemarse.', 'Pizza napolitana', false),
  (87, 'Pizza de jamón y morrones', 'Un clásico de pizzería: muzzarella, jamón y tiras de morrón.', 'Pizzas', 25, 'Fácil', 2, '🍕', 'Asá el morrón antes y pelalo: queda más dulce y suave.', 'Pizza', false),
  (88, 'Pizza con rúcula y jamón crudo', 'Muzzarella gratinada y, al salir del horno, rúcula fresca y jamón crudo.', 'Pizzas', 25, 'Fácil', 2, '🍕', 'La rúcula y el crudo van después de hornear, así no se cocinan.', 'Pizza', false),
  (89, 'Fainá', 'Masa fina de harina de garbanzo, crocante por fuera. Para comer con pizza o sola.', 'Pizzas', 40, 'Fácil', 4, '🟡', 'Dejá reposar la mezcla al menos 30 minutos: queda más suave y no se rompe.', 'Fainá', false),
  (90, 'Pollo a la cerveza', 'Presas de pollo cocinadas en cerveza con cebolla, morrón y papas.', 'Pollo', 70, 'Fácil', 4, '🍺', 'Usá cerveza rubia: la negra puede dejarlo amargo.', 'Pollo guisado', false),
  (91, 'Pollo al curry', 'Pechuga en una salsa cremosa de curry. Con arroz blanco es una cena completa.', 'Pollo', 35, 'Fácil', 4, '🍛', 'Tostá el curry un minuto en el aceite antes de agregar el líquido: suelta todo su aroma.', 'Pollo al curry', false),
  (92, 'Wok de pollo y verduras', 'Pollo salteado con verduras crocantes y salsa de soja, en 20 minutos.', 'Pollo', 25, 'Fácil', 2, '🥢', 'Todo a fuego máximo y moviendo siempre: las verduras tienen que quedar crocantes.', 'Wok', false),
  (93, 'Suprema a la napolitana', 'Suprema de pollo empanada con salsa, jamón y muzzarella gratinada.', 'Pollo', 45, 'Fácil', 4, '🍕', 'Aplastá bien las supremas para que se cocinen parejas.', 'Milanesa a la napolitana', false),
  (94, 'Pollo a la crema con champiñones', 'Pechuga en cubos con champiñones en una salsa cremosa.', 'Pollo', 30, 'Fácil', 4, '🍄', 'Dorá bien los champiñones sin moverlos mucho: así no largan agua.', 'Agaricus bisporus', false),
  (95, 'Alitas de pollo a la barbacoa', 'Alitas al horno, crocantes y glaseadas.', 'Pollo', 55, 'Fácil', 4, '🍗', 'Secá muy bien las alitas antes de condimentarlas: quedan más crocantes.', 'Alitas de pollo', false),
  (96, 'Pollo agridulce con ananá', 'Pollo salteado con morrones y ananá en salsa agridulce, con arroz.', 'Pollo', 35, 'Media', 4, '🍍', 'Usá el almíbar del ananá para la salsa en lugar de azúcar.', 'Pollo agridulce', false),
  (97, 'Fajitas de pollo', 'Tiras de pollo con morrones y cebolla en tortillas de trigo, con palta.', 'Pollo', 30, 'Fácil', 4, '🌮', 'Llevá todo a la mesa y que cada uno arme la suya.', 'Fajita', false),
  (98, 'Pollo al ajillo', 'Presas doradas con mucho ajo, vino blanco y perejil.', 'Pollo', 50, 'Fácil', 4, '🧄', 'Agregá el ajo cuando el pollo ya está dorado: si se quema, amarga.', 'Pollo al ajillo', false),
  (99, 'Salmón al horno con verduras', 'Filet de salmón con limón, zucchini y tomates cherry, todo en una fuente.', 'Pescados', 30, 'Fácil', 2, '🐟', 'El salmón está listo cuando se separa en láminas al presionarlo; no lo cocines de más.', 'Salmón (alimento)', false),
  (100, 'Langostinos al ajillo', 'Langostinos salteados en aceite de oliva con ajo y un toque picante.', 'Pescados', 15, 'Fácil', 2, '🦐', 'Se cocinan en 2 minutos: apenas se ponen rosados, están listos.', 'Pleoticus muelleri', false),
  (101, 'Rabas', 'Anillos de calamar rebozados y fritos, con limón.', 'Pescados', 30, 'Fácil', 2, '🦑', 'Freílas en tandas chicas y en aceite bien caliente para que no queden aceitosas.', 'Rabas', false),
  (102, 'Paella', 'Arroz con mariscos, pollo y verduras, con azafrán. Para una cena especial.', 'Pescados', 70, 'Difícil', 6, '🥘', 'No revuelvas el arroz una vez que agregaste el caldo: así se forma el socarrat abajo.', 'Paella', false),
  (103, 'Merluza al horno con papas', 'Filet de merluza sobre papas y cebolla, con limón y vino blanco.', 'Pescados', 50, 'Fácil', 4, '🐟', 'Las papas van primero: el pescado necesita mucho menos tiempo.', 'Merluccius hubbsi', false),
  (104, 'Trucha a la manteca con alcaparras', 'Filet de trucha dorado en manteca, con limón y alcaparras.', 'Pescados', 20, 'Fácil', 2, '🐟', 'Empezá con la piel hacia abajo y no la muevas: se pone crocante.', 'Oncorhynchus mykiss', false),
  (105, 'Croquetas de atún', 'Croquetas de papa y atún, doradas por fuera y suaves por dentro.', 'Pescados', 50, 'Fácil', 4, '🐟', 'Enfriá la mezcla 30 minutos antes de formarlas: se manejan mucho mejor.', 'Croqueta', false),
  (106, 'Mejillones a la provenzal', 'Mejillones abiertos al vapor con vino blanco, ajo y perejil.', 'Pescados', 25, 'Fácil', 2, '🦪', 'Descartá los mejillones que no se abran después de cocinarse.', 'Mytilus', false),
  (107, 'Fideos con atún y tomate', 'Una salsa de tomate con atún, ajo y aceitunas. Lista en lo que se cocinan los fideos.', 'Pastas', 20, 'Fácil', 4, '🍝', 'Agregá el atún al final para que no se deshaga.', 'Espaguetis', false),
  (108, 'Ravioles con tuco', 'Ravioles comprados con un tuco casero, como el domingo en familia.', 'Pastas', 40, 'Fácil', 4, '🥟', 'Hervilos a fuego medio: si el agua hierve fuerte, los ravioles se abren.', 'Ravioli', false),
  (109, 'Sorrentinos con salsa rosa', 'Sorrentinos con una salsa de tomate y crema, suave y cremosa.', 'Pastas', 30, 'Fácil', 4, '🥟', 'La salsa rosa es tuco con crema: no dejes hervir fuerte después de agregarla.', 'Sorrentinos', false),
  (110, 'Lasaña de carne', 'Capas de pasta, bolognesa, salsa blanca y muzzarella gratinada.', 'Pastas', 100, 'Media', 6, '🍝', 'Dejala reposar 10 minutos antes de cortar para que las capas no se desarmen.', 'Lasaña', false),
  (111, 'Lasaña de verdura', 'Acelga o espinaca con ricota, salsa blanca y queso.', 'Pastas', 90, 'Media', 6, '🥬', 'Escurrí muy bien la verdura: si no, la lasaña queda aguada.', 'Lasaña', false),
  (112, 'Tallarines al pesto', 'Pasta con pesto casero de albahaca, ajo, queso y nueces.', 'Pastas', 20, 'Fácil', 4, '🌿', 'No calientes el pesto: mezclalo con la pasta recién escurrida y listo.', 'Pesto', false),
  (113, 'Fideos a la bolognesa', 'Salsa de carne picada y tomate, cocinada despacio.', 'Pastas', 50, 'Fácil', 4, '🍝', 'Cuanto más tiempo se cocina la salsa, mejor queda.', 'Salsa boloñesa', false),
  (114, 'Fideos a la carbonara', 'Panceta dorada, huevo y queso: una salsa cremosa sin crema.', 'Pastas', 20, 'Media', 4, '🥓', 'Mezclá el huevo fuera del fuego, con el calor de la pasta: si no, se hace revuelto.', 'Spaghetti alla carbonara', false),
  (115, 'Fideos con brócoli y ajo', 'Brócoli salteado con ajo, aceite de oliva y un toque picante.', 'Pastas', 20, 'Fácil', 4, '🥦', 'Hervé el brócoli en la misma agua de los fideos: ahorrás tiempo y ollas.', 'Brócoli', false),
  (116, 'Ñoquis a los cuatro quesos', 'Ñoquis con una salsa cremosa de queso azul, muzzarella y queso rallado.', 'Pastas', 20, 'Fácil', 4, '🧀', 'Si el queso azul es fuerte para tu gusto, usá menos y más muzzarella.', 'Ñoquis', false),
  (117, 'Fideos con salsa de hongos', 'Champiñones y hongos de pino en una salsa cremosa.', 'Pastas', 30, 'Fácil', 4, '🍄', 'Usá el agua de hidratar los hongos secos en la salsa: tiene muchísimo sabor.', 'Agaricus bisporus', false),
  (118, 'Risotto de hongos', 'Arroz cremoso con hongos, vino blanco y queso.', 'Pastas', 40, 'Media', 4, '🍚', 'Agregá el caldo de a un cucharón y revolvé siempre: eso le da la cremosidad.', 'Risotto', false),
  (119, 'Risotto de calabaza', 'Arroz cremoso con calabaza, queso y un toque de nuez moscada.', 'Pastas', 40, 'Media', 4, '🎃', 'La calabaza en cubos chiquitos se deshace y le da color y cremosidad.', 'Risotto', false),
  (120, 'Guiso de porotos con chorizo', 'Porotos blancos con chorizo, panceta y zapallo. Bien de invierno.', 'Guisos y sopas', 90, 'Fácil', 6, '🫘', 'Si usás porotos en lata, ahorrás el remojo y la primera cocción.', 'Phaseolus vulgaris', false),
  (121, 'Crema de calabaza', 'Sopa crema de calabaza, suave y reconfortante.', 'Guisos y sopas', 40, 'Fácil', 4, '🥣', 'Terminala con un hilo de crema y semillas tostadas.', 'Crema de calabaza', false),
  (122, 'Sopa de arvejas partidas', 'Sopa espesa de arvejas con panceta y verduras.', 'Guisos y sopas', 70, 'Fácil', 4, '🥣', 'No hace falta remojar las arvejas partidas, pero enjuagalas bien.', 'Guisante partido', false),
  (123, 'Sopa de cebolla gratinada', 'Cebollas caramelizadas en caldo, con pan y queso gratinado.', 'Guisos y sopas', 60, 'Media', 4, '🧅', 'La paciencia es la clave: las cebollas tienen que dorarse despacio.', 'Sopa de cebolla', false),
  (124, 'Porotos negros con arroz', 'Porotos negros guisados con panceta y chorizo, servidos con arroz blanco.', 'Guisos y sopas', 100, 'Fácil', 4, '🫘', 'Remojalos la noche anterior y cambiales el agua antes de cocinar.', 'Frijol negro', false),
  (125, 'Caldo de pollo con fideos', 'Sopa casera de pollo y verduras con fideos finos.', 'Guisos y sopas', 60, 'Fácil', 4, '🥣', 'Sacá la espuma del principio con una espumadera: el caldo queda más limpio.', 'Sopa de pollo', false),
  (126, 'Coliflor gratinada', 'Coliflor con salsa blanca y queso gratinado al horno.', 'Vegetariano', 45, 'Fácil', 4, '🥦', 'Escurrí bien la coliflor antes de cubrirla con la salsa.', 'Coliflor', false),
  (127, 'Berenjenas rellenas', 'Berenjenas rellenas con su pulpa, verduras y queso. Con o sin carne.', 'Vegetariano', 60, 'Fácil', 4, '🍆', 'Hacé cortes en la pulpa y salala antes de hornear para que se cocine pareja.', 'Solanum melongena', false),
  (128, 'Morrones rellenos', 'Morrones asados rellenos de arroz, carne y queso.', 'Carnes', 60, 'Fácil', 4, '🫑', 'Elegí morrones que se paren solos para que no se vuelquen en el horno.', 'Pimiento relleno', false),
  (129, 'Tomates rellenos de atún', 'Tomates frescos rellenos de atún, arroz y mayonesa. Cena fresca de verano.', 'Ensaladas', 30, 'Fácil', 4, '🍅', 'Dejá los tomates boca abajo 10 minutos para que larguen el jugo.', 'Tomate relleno', false),
  (130, 'Papas gratinadas', 'Papas en rodajas finas con crema y queso, gratinadas al horno.', 'Vegetariano', 70, 'Fácil', 4, '🥔', 'Cortá las papas bien finas y parejas, mejor con mandolina.', 'Gratin dauphinois', false),
  (131, 'Arroz salteado con huevo y verduras', 'Arroz frito al estilo oriental con huevo, verduras y salsa de soja. Ideal para usar arroz del día anterior.', 'Vegetariano', 25, 'Fácil', 2, '🍳', 'Usá arroz frío del día anterior: queda suelto y no se pega.', 'Arroz frito', false),
  (132, 'Quinoa con verduras salteadas', 'Quinoa con zucchini, morrón y zanahoria salteados. Liviana y completa.', 'Vegetariano', 30, 'Fácil', 2, '🌾', 'Lavá bien la quinoa antes de cocinarla para sacarle el amargor.', 'Chenopodium quinoa', false),
  (133, 'Cuscús con verduras y garbanzos', 'Cuscús especiado con verduras salteadas y garbanzos.', 'Vegetariano', 25, 'Fácil', 4, '🫘', 'El cuscús no se hierve: se hidrata tapado con agua o caldo caliente.', 'Cuscús', false),
  (134, 'Revuelto de chauchas', 'Chauchas salteadas con cebolla, ajo y huevo.', 'Vegetariano', 25, 'Fácil', 2, '🫛', 'Cociná las chauchas al dente: tienen que seguir un poco crocantes.', 'Judía verde', false),
  (135, 'Omelette de jamón y queso', 'Omelette esponjoso relleno de jamón y queso. Cena en 10 minutos.', 'Minutas', 10, 'Fácil', 1, '🍳', 'Fuego medio-bajo: el omelette tiene que quedar dorado apenas y húmedo por dentro.', 'Omelette', false),
  (136, 'Ensalada de remolacha y huevo', 'Remolacha hervida con huevo duro, cebolla y vinagreta.', 'Ensaladas', 50, 'Fácil', 4, '🟣', 'Hervila con cáscara y pelala después: no pierde color.', 'Beta vulgaris', false),
  (137, 'Ensalada de rúcula y parmesano', 'Rúcula con tomates cherry, láminas de queso y aceite de oliva.', 'Ensaladas', 10, 'Fácil', 2, '🥗', 'Usá un pelapapas para sacar láminas finas del queso.', 'Eruca vesicaria', false),
  (138, 'Ensalada César', 'Lechuga, pollo grillado, croutons y aderezo cremoso.', 'Ensaladas', 30, 'Fácil', 2, '🥗', 'Hacé los croutons con pan del día anterior.', 'Ensalada César', false),
  (139, 'Ensalada de lentejas', 'Lentejas con tomate, cebolla, morrón y perejil. Fría y llena de proteína.', 'Ensaladas', 35, 'Fácil', 4, '🫘', 'Condimentalas tibias: absorben mejor el aderezo.', 'Lens culinaris', false),
  (140, 'Ensalada caprese', 'Tomate, muzzarella y albahaca con aceite de oliva. Simple y fresca.', 'Ensaladas', 10, 'Fácil', 2, '🍅', 'Usá tomates bien maduros y a temperatura ambiente.', 'Ensalada caprese', false)
ON CONFLICT ("Id") DO UPDATE SET
    "Nombre" = EXCLUDED."Nombre",
    "Descripcion" = EXCLUDED."Descripcion",
    "Categoria" = EXCLUDED."Categoria",
    "TiempoMin" = EXCLUDED."TiempoMin",
    "Dificultad" = EXCLUDED."Dificultad",
    "Porciones" = EXCLUDED."Porciones",
    "Emoji" = EXCLUDED."Emoji",
    "Consejo" = EXCLUDED."Consejo",
    "ImagenUrl" = CASE WHEN "Recetas"."BusquedaImagen" IS DISTINCT FROM EXCLUDED."BusquedaImagen" THEN NULL ELSE "Recetas"."ImagenUrl" END,
    "BusquedaImagen" = EXCLUDED."BusquedaImagen",
    "EsPersonalizada" = false;

