-- 8) Pasos de cada receta, con fuego y tapa
INSERT INTO "RecetaPasos" ("RecetaId", "Numero", "Titulo", "Descripcion", "Minutos", "Fuego", "Tapa") VALUES
  (1, 1, 'Preparar la carne', 'Si la carne no viene cortada, cortala en bifes de medio centímetro, siempre en contra de la fibra. Ponelos dentro de una bolsa y golpealos suavemente con un palo de amasar para emparejar el grosor: así se cocinan parejo y quedan tiernos.', NULL, NULL, NULL),
  (1, 2, 'Hacer el batido', 'En un bowl batí los huevos con el ajo bien picado, el perejil, sal y pimienta. Pasá cada bife por el batido y dejalos reposar unos 15 minutos para que tomen sabor (si tenés tiempo, toda la noche en la heladera es mejor).', 15, NULL, NULL),
  (1, 3, 'Empanar', 'Pasá cada milanesa por pan rallado y presioná con la palma de la mano de los dos lados para que se adhiera bien. Si te gustan con más cobertura, repetí huevo y pan rallado una vez más.', NULL, NULL, NULL),
  (1, 4, 'Cocinar las milanesas', 'Precalentá el horno a 200 °C. Aceitá una placa, acomodá las milanesas sin encimarlas y rociá un hilo de aceite por arriba. Horneá 10 minutos, dalas vuelta y cociná 8 a 10 minutos más, hasta que estén doradas de ambos lados.', 20, 'Horno 200 °C', NULL),
  (1, 5, 'Hervir las papas', 'Mientras tanto, pelá las papas, cortalas en cubos parejos y ponelas en una olla con agua fría y sal. Cuando rompa el hervor, cociná 15 a 20 minutos, hasta que un cuchillo entre sin resistencia. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 20, 'Fuerte, después medio', 'Destapado'),
  (1, 6, 'Hacer el puré', 'Escurrí muy bien y pisá las papas en caliente. Agregá la manteca, la leche tibia de a poco, sal y una pizca de nuez moscada. Mezclá con cuchara de madera hasta que esté cremoso; evitá la minipimer porque el puré queda gomoso. Fuera del fuego.', NULL, 'Fuera del fuego', NULL),
  (1, 7, 'Servir', 'Serví las milanesas recién salidas del horno junto al puré. Unas gotas de limón por arriba le dan el toque final.', NULL, NULL, NULL),
  (2, 1, 'Empanar', 'Batí los huevos con el ajo picado, sal y pimienta. Pasá los bifes por el huevo y después por pan rallado, presionando bien con la mano.', NULL, NULL, NULL),
  (2, 2, 'Cocinar la milanesa', 'Horneá las milanesas en una placa aceitada a 200 °C durante 10 minutos por lado, o freílas en aceite caliente 2 a 3 minutos por lado. Escurrilas sobre papel absorbente si las freíste.', 20, 'Horno 200 °C', NULL),
  (2, 3, 'Preparar la salsa', 'Calentá el puré de tomate en una sartén con una pizca de sal, orégano y un chorrito de aceite. Cociná 5 minutos a fuego bajo hasta que espese un poco. Sin tapa.', 5, 'Fuego bajo', 'Destapado'),
  (2, 4, 'Armar', 'Sobre cada milanesa poné dos cucharadas de salsa, una feta de jamón, rodajas de tomate si tenés y abundante muzzarella en fetas o rallada. Terminá con orégano.', NULL, NULL, NULL),
  (2, 5, 'Gratinar', 'Llevá al horno fuerte (220 °C) unos 8 minutos, hasta que el queso se derrita y empiece a dorarse en los bordes.', 8, 'Horno 220 °C', NULL),
  (2, 6, 'Servir', 'Servila caliente. Va perfecta con papas fritas, puré o una ensalada mixta.', NULL, NULL, NULL),
  (3, 1, 'Hervir los huevos', 'Poné 2 huevos en agua fría y, cuando rompa el hervor, contá 10 minutos. Pasalos a agua fría, pelalos y cortalos en cubitos. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 10, 'Fuerte, después medio', 'Destapado'),
  (3, 2, 'Rehogar la cebolla', 'Picá la cebolla, el morrón y la parte blanca del verdeo. Cocinalos en una sartén grande con un chorro de aceite a fuego medio unos 10 minutos, hasta que estén transparentes y blandos. Sin tapa.', 10, 'Fuego medio', 'Destapado'),
  (3, 3, 'Cocinar la carne', 'Subí el fuego, agregá la carne y desarmala con una cuchara. Cociná hasta que pierda el color rosado, unos 8 minutos. Condimentá con sal, pimienta, comino, pimentón y ají molido. Hacelo a fuego fuerte y sin tapa.', 8, 'Fuego fuerte', 'Destapado'),
  (3, 4, 'Enfriar el relleno', 'Sumá el verde del verdeo picado, mezclá y pasá el relleno a una fuente. Dejalo enfriar por completo; idealmente 1 hora en la heladera, así la grasa se solidifica y las empanadas quedan jugosas.', 60, NULL, NULL),
  (3, 5, 'Armar', 'Sobre cada tapa poné una cucharada generosa de relleno, un poco de huevo duro y media aceituna. Humedecé el borde con agua, cerrá en forma de media luna y hacé el repulgue o apretá el borde con un tenedor.', NULL, NULL, NULL),
  (3, 6, 'Hornear', 'Precalentá el horno a 220 °C. Acomodá las empanadas en una placa enmantecada o con papel manteca y pintalas con el huevo batido. Horneá 15 a 18 minutos, hasta que estén bien doradas.', 18, 'Horno 220 °C', NULL),
  (4, 1, 'Preparar el molde', 'Precalentá el horno a 200 °C. Enmantecá o aceitá una tartera de unos 26 cm y forrala con una de las tapas, dejando que sobresalga un poco del borde. Pinchá la base con un tenedor.', NULL, NULL, NULL),
  (4, 2, 'Opcional: rehogar cebolla', 'Si usás cebolla, picala fina y rehogala en una sartén con un poco de aceite 8 minutos, hasta que esté transparente. Dejala entibiar. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (4, 3, 'Preparar el relleno', 'Cortá el jamón y el queso en cubitos. En un bowl batí los huevos con la crema, sal, pimienta y nuez moscada. Sumá el jamón, el queso y la cebolla.', NULL, NULL, NULL),
  (4, 4, 'Rellenar y tapar', 'Volcá el relleno sobre la masa. Cubrí con la segunda tapa, uní los bordes doblándolos hacia adentro y hacé un pequeño corte en el centro para que salga el vapor.', NULL, NULL, NULL),
  (4, 5, 'Hornear', 'Horneá 30 a 35 minutos, hasta que la tapa esté dorada. Dejala reposar 10 minutos antes de cortar para que el relleno se asiente. Horno a 200 °C.', 35, 'Horno 200 °C', NULL),
  (5, 1, 'Limpiar la acelga', 'Separá las hojas de los tallos gruesos (podés guardar los tallos para una sopa). Lavá bien las hojas en abundante agua.', NULL, NULL, NULL),
  (5, 2, 'Cocinar la acelga', 'Hervila 3 minutos en agua con sal o cocinala tapada en una sartén solo con el agua que le queda del lavado. Escurrila, apretala con las manos para sacarle todo el líquido y picala. Hacelo a fuego medio.', 5, 'Fuego medio', 'Tapado'),
  (5, 3, 'Rehogar', 'Picá la cebolla y el ajo y rehogalos con aceite a fuego medio 10 minutos. Agregá la acelga picada, mezclá 2 minutos y apagá el fuego. Sin tapa.', 12, 'Fuego medio', 'Destapado'),
  (5, 4, 'Mezclar el relleno', 'Cuando esté tibio, agregá los huevos batidos, el queso rallado, el cremoso en cubos, sal, pimienta y nuez moscada.', NULL, NULL, NULL),
  (5, 5, 'Armar y hornear', 'Forrá una tartera aceitada con una tapa, rellená, cubrí con la otra tapa y cerrá los bordes. Pinchá la superficie y horneá a 200 °C de 35 a 40 minutos, hasta que esté dorada.', 40, 'Horno 200 °C', NULL),
  (6, 1, 'Cocinar la espinaca', 'Lavá la espinaca, cocinala 2 minutos en una olla tapada con apenas agua, escurrila muy bien apretándola y picala. Hacelo a fuego medio.', 5, 'Fuego medio', 'Tapado'),
  (6, 2, 'Rehogar la cebolla', 'Picá la cebolla y rehogala con aceite 8 minutos. Sumá la espinaca, salpimentá y dejá entibiar. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (6, 3, 'Mezclar con ricota', 'Uní la espinaca con la ricota, 2 huevos batidos, el queso rallado y la nuez moscada. Probá y ajustá la sal.', NULL, NULL, NULL),
  (6, 4, 'Armar', 'Forrá una tartera aceitada con una tapa y volcá el relleno. Hacé 4 huecos con el dorso de una cuchara y rompé un huevo entero dentro de cada uno. Salpimentá los huevos.', NULL, NULL, NULL),
  (6, 5, 'Tapar y hornear', 'Cubrí con la segunda tapa, cerrá los bordes con un repulgue y pinchá la superficie sin llegar a los huevos. Horneá a 200 °C unos 40 minutos, hasta que esté dorada.', 40, 'Horno 200 °C', NULL),
  (7, 1, 'Remojar las lentejas', 'Si tenés tiempo, dejá las lentejas en remojo 2 horas (no es obligatorio, pero se cocinan más rápido y caen mejor). Enjuagalas antes de usar.', 120, NULL, NULL),
  (7, 2, 'Dorar las carnes', 'En una olla grande con un chorrito de aceite dorá el chorizo en rodajas, la panceta y la carne en cubos, unos 8 minutos. Retirá y reservá. Hacelo a fuego medio-fuerte y sin tapa.', 8, 'Fuego medio-fuerte', 'Destapado'),
  (7, 3, 'Hacer el sofrito', 'En la misma olla rehogá la cebolla, el morrón y el ajo picados durante 8 minutos. Agregá la zanahoria en rodajas y el pimentón, y revolvé un minuto sin que se queme. Hacelo a fuego medio y sin tapa.', 9, 'Fuego medio', 'Destapado'),
  (7, 4, 'Sumar las lentejas', 'Volvé a poner las carnes, agregá las lentejas, el puré de tomate, el laurel, el comino y el caldo disuelto en 1,5 litros de agua caliente.', NULL, NULL, NULL),
  (7, 5, 'Cocinar', 'Cuando hierva, bajá a fuego mínimo y cociná tapado 25 minutos. Sumá la papa y el zapallo en cubos y seguí 20 minutos más, revolviendo de vez en cuando. Si se seca, agregá agua caliente.', 45, 'Fuego mínimo', 'Tapado'),
  (7, 6, 'Ajustar y servir', 'Probá de sal, retirá las hojas de laurel y dejá reposar 10 minutos con el fuego apagado. Serví bien caliente.', NULL, NULL, NULL),
  (8, 1, 'Remojar la noche anterior', 'Poné el maíz y los porotos en remojo por separado, cubiertos con abundante agua, durante toda la noche (al menos 12 horas).', 720, NULL, NULL),
  (8, 2, 'Primer hervor', 'Escurrí, poné el maíz y los porotos en una olla grande con 4 litros de agua y llevá a hervor. Cociná 1 hora a fuego bajo, sacando la espuma que se forma arriba. Con la tapa apenas corrida.', 60, 'Fuego bajo', 'Semitapado'),
  (8, 3, 'Sumar las carnes', 'Agregá la carne en cubos, el chorizo en rodajas y la panceta en cubitos. Seguí cocinando a fuego bajo, revolviendo seguido. Con la tapa apenas corrida.', 30, 'Fuego bajo', 'Semitapado'),
  (8, 4, 'Agregar el zapallo y la cebolla', 'Sumá el zapallo pelado en cubos y la cebolla picada. Condimentá con sal, comino y 1 cucharada de pimentón. Cociná 1 hora y media más, hasta que el zapallo se deshaga y el locro espese. Si hace falta, agregá agua caliente. Hacelo a fuego bajo, con la tapa apenas corrida.', 90, 'Fuego bajo', 'Semitapado'),
  (8, 5, 'Preparar la salsita', 'En una sartén calentá 6 cucharadas de aceite, apagá el fuego y agregá el pimentón restante, el ají molido y el verdeo picado. Mezclá: tiene que quedar una salsa roja y brillante.', NULL, 'Fuera del fuego', NULL),
  (8, 6, 'Servir', 'Serví el locro en cazuelas bien caliente con una cucharada de salsita por encima.', NULL, NULL, NULL),
  (9, 1, 'Sellar la carne', 'Cortá la carne en cubos de 2 cm y dorala en una olla grande con aceite a fuego fuerte, en tandas para que no hierva en su jugo. Reservá. Sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (9, 2, 'Sofrito', 'En la misma olla rehogá la cebolla y el morrón picados 8 minutos. Sumá el tomate picado y el pimentón y cociná 5 minutos más. Hacelo a fuego medio y sin tapa.', 13, 'Fuego medio', 'Destapado'),
  (9, 3, 'Cocinar la carne', 'Volvé a poner la carne, cubrí con 1 litro de caldo caliente y cociná tapado a fuego bajo 30 minutos.', 30, 'Fuego bajo', 'Tapado'),
  (9, 4, 'Agregar las verduras', 'Sumá la papa, la batata y el zapallo en cubos y los choclos cortados en rodajas. Si usás arroz, agregalo ahora. Cociná 25 minutos más, hasta que todo esté tierno. Hacelo a fuego bajo, con la olla tapada.', 25, 'Fuego bajo', 'Tapado'),
  (9, 5, 'Los duraznos', 'Cortá los duraznos en cubos y agregalos en los últimos 5 minutos, junto con un poco de su almíbar si te gusta más dulce. Ajustá la sal y serví. Hacelo a fuego bajo, con la olla tapada.', 5, 'Fuego bajo', 'Tapado'),
  (10, 1, 'Hacer el puré', 'Hervé las papas peladas y en cubos en agua con sal 20 minutos. Escurrí, pisalas con la manteca, la leche, sal y nuez moscada. Cuando esté tibio, sumá un huevo batido. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 25, 'Fuerte, después medio', 'Destapado'),
  (10, 2, 'Preparar la carne', 'Rehogá la cebolla y el morrón picados en aceite 8 minutos. Agregá la carne, desgranándola, y cociná hasta que pierda el color. Condimentá con sal, pimienta, comino y pimentón. Hacelo a fuego medio y sin tapa.', 15, 'Fuego medio', 'Destapado'),
  (10, 3, 'Agregar los extras', 'Si querés, sumá el huevo duro picado y las aceitunas en rodajas al relleno. Mezclá y apagá.', NULL, NULL, NULL),
  (10, 4, 'Armar', 'En una fuente para horno aceitada distribuí la carne y cubrila con el puré, alisando con una espátula. Marcá la superficie con un tenedor y espolvoreá queso rallado y, si te gusta, azúcar.', NULL, NULL, NULL),
  (10, 5, 'Gratinar', 'Horneá a 200 °C unos 20 minutos, hasta que la superficie esté dorada. Dejá reposar 5 minutos antes de servir.', 20, 'Horno 200 °C', NULL),
  (11, 1, 'Cortar las papas', 'Pelá las papas y cortalas en láminas finas o en cubitos pequeños. Si usás cebolla, cortala en pluma fina. Salá todo.', NULL, NULL, NULL),
  (11, 2, 'Confitar', 'Calentá abundante aceite en una sartén a fuego medio y cociná las papas (y la cebolla) unos 15 minutos, moviéndolas, hasta que estén tiernas pero sin dorarse mucho. Escurrilas bien en un colador. Sin tapa.', 15, 'Fuego medio', 'Destapado'),
  (11, 3, 'Mezclar con el huevo', 'Batí los huevos con sal en un bowl grande, agregá las papas calientes y dejá reposar 5 minutos para que se integren.', 5, NULL, NULL),
  (11, 4, 'Cuajar el primer lado', 'En una sartén antiadherente de 24 cm con una cucharada de aceite bien caliente, volcá la mezcla. Bajá el fuego y cociná 5 minutos, despegando los bordes con una espátula. Hacelo a fuego bajo y sin tapa.', 5, 'Fuego bajo', 'Destapado'),
  (11, 5, 'Dar vuelta', 'Tapá con un plato, invertí la tortilla y deslizala de nuevo en la sartén. Cociná 2 a 3 minutos más si la querés jugosa, o 5 si la preferís bien cocida. Hacelo a fuego bajo.', 4, 'Fuego bajo', NULL),
  (12, 1, 'Cortar las papas pay', 'Pelá las papas y cortalas en bastones muy finos (tipo fósforo). Lavalas en agua fría y secalas muy bien con un repasador.', NULL, NULL, NULL),
  (12, 2, 'Freír', 'Freílas en aceite bien caliente, en tandas, hasta que estén doradas y crocantes. Escurrí sobre papel absorbente y salá. Hacelo a fuego medio-fuerte y sin tapa.', 10, 'Fuego medio-fuerte', 'Destapado'),
  (12, 3, 'Saltear', 'En una sartén grande con un poco de aceite rehogá la cebolla en pluma 5 minutos. Sumá el jamón en tiritas y las arvejas escurridas, y salteá 2 minutos. Hacelo a fuego medio y sin tapa.', 7, 'Fuego medio', 'Destapado'),
  (12, 4, 'Revolver con huevo', 'Agregá las papas, bajá el fuego y volcá los huevos batidos con sal y pimienta. Revolvé suavemente hasta que el huevo esté cremoso. Hacelo a fuego bajo y sin tapa.', 3, 'Fuego bajo', 'Destapado'),
  (12, 5, 'Servir', 'Serví enseguida con perejil picado por encima.', NULL, NULL, NULL),
  (13, 1, 'Sofrito', 'En una cacerola con aceite rehogá a fuego medio la cebolla, el morrón y el ajo bien picados durante 10 minutos. Si usás zanahoria rallada, sumala a mitad de camino. Sin tapa.', 10, 'Fuego medio', 'Destapado'),
  (13, 2, 'Cocinar el tuco', 'Agregá el puré de tomate, medio vaso de agua, el laurel, el orégano, la pizca de azúcar, sal y pimienta. Cociná tapado a fuego mínimo 20 minutos, revolviendo cada tanto.', 20, 'Fuego mínimo', 'Tapado'),
  (13, 3, 'Hervir los fideos', 'En una olla grande llevá a hervor abundante agua (1 litro cada 100 g de fideos) con sal. Cociná los fideos el tiempo que indica el paquete, probando un minuto antes para que queden al dente. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (13, 4, 'Unir', 'Escurrí los fideos, mezclalos con parte del tuco en la olla y serví con más salsa por encima, hojas de albahaca y queso rallado.', NULL, NULL, NULL),
  (14, 1, 'Hervir las papas con cáscara', 'Lavá las papas y hervilas enteras, con cáscara, unos 30 minutos hasta que estén tiernas. Con cáscara absorben menos agua. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 30, 'Fuerte, después medio', 'Destapado'),
  (14, 2, 'Hacer el puré', 'Pelalas todavía calientes y pisalas o pasalas por un pisapapas hasta que no queden grumos. Extendé el puré en la mesada para que largue el vapor y se entibie.', 10, NULL, NULL),
  (14, 3, 'Formar la masa', 'Agregá el huevo, sal, nuez moscada, el queso rallado y la harina de a poco. Uní con las manos sin amasar demasiado, solo hasta que la masa no se pegue.', NULL, NULL, NULL),
  (14, 4, 'Cortar', 'Hacé cilindros de 2 cm de grosor sobre la mesada enharinada y cortalos en trozos de 2 cm. Si querés la forma clásica, pasá cada ñoqui por un tenedor.', NULL, NULL, NULL),
  (14, 5, 'Preparar la salsa', 'Rehogá el ajo picado en aceite 1 minuto, sumá el puré de tomate y sal, y cociná 15 minutos a fuego bajo. Si preferís, derretí manteca para servirlos con queso. Sin tapa.', 15, 'Fuego bajo', 'Destapado'),
  (14, 6, 'Hervir', 'Cociná los ñoquis en abundante agua hirviendo con sal, en tandas. Cuando suben a la superficie están listos: retiralos con espumadera directo a la salsa. Hacelo a fuego medio y sin tapa.', 3, 'Fuego medio', 'Destapado'),
  (15, 1, 'Dorar el pollo', 'Salpimentá las presas y dorálas en una olla grande con aceite a fuego fuerte, unos 5 minutos por lado. Retiralas y reservá. Sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (15, 2, 'Sofrito', 'En la misma olla rehogá la cebolla, los morrones y el ajo picados 8 minutos. Sumá el tomate picado y el pimentón. Si usás vino, agregalo y dejá que se evapore el alcohol 2 minutos. Hacelo a fuego medio y sin tapa.', 10, 'Fuego medio', 'Destapado'),
  (15, 3, 'Cocinar el pollo', 'Volvé el pollo a la olla, cubrí con 1 litro de caldo caliente y cociná tapado a fuego bajo 20 minutos.', 20, 'Fuego bajo', 'Tapado'),
  (15, 4, 'Agregar el arroz', 'Sumá el arroz, mezclá una sola vez y agregá más caldo si hace falta (tiene que haber el doble de líquido que de arroz). Cociná tapado a fuego bajo 18 minutos sin revolver.', 18, 'Fuego bajo', 'Tapado'),
  (15, 5, 'Terminar', 'Agregá las arvejas escurridas, apagá el fuego y dejá reposar tapado 5 minutos antes de servir.', 5, 'Fuera del fuego', 'Tapado'),
  (16, 1, 'Marinar', 'En un bowl mezclá el jugo del limón, el ajo picado, orégano, pimentón, sal, pimienta y 3 cucharadas de aceite. Untá bien las presas y dejalas reposar al menos 30 minutos.', 30, NULL, NULL),
  (16, 2, 'Preparar las verduras', 'Precalentá el horno a 200 °C. Pelá las papas (y las batatas) y cortalas en gajos. Cortá la cebolla en aros gruesos. Acomodá todo en una asadera aceitada y salá.', NULL, NULL, NULL),
  (16, 3, 'Hornear', 'Poné las presas encima de las verduras, con la piel hacia arriba, y rociá con el resto de la marinada y el vino si usás. Horneá 30 minutos. Horno a 200 °C.', 30, 'Horno 200 °C', NULL),
  (16, 4, 'Dar vuelta y dorar', 'Girá las presas y mové las papas. Horneá 25 a 30 minutos más, hasta que el pollo esté dorado y al pincharlo salga jugo transparente. Horno a 200 °C.', 30, 'Horno 200 °C', NULL),
  (16, 5, 'Servir', 'Dejá reposar 5 minutos y serví con el jugo de la asadera por encima.', NULL, NULL, NULL),
  (17, 1, 'Preparar las pechugas', 'Cortá cada pechuga a la mitad para obtener 4 supremas y abrilas en mariposa. Aplastalas entre dos films hasta que tengan 1 cm de grosor parejo.', NULL, NULL, NULL),
  (17, 2, 'Batido', 'Batí los huevos con ajo y perejil picados, la mostaza si usás, sal y pimienta. Pasá las supremas y dejalas 10 minutos.', 10, NULL, NULL),
  (17, 3, 'Empanar', 'Pasalas por pan rallado presionando bien de los dos lados.', NULL, NULL, NULL),
  (17, 4, 'Cocinar', 'Horneá en placa aceitada a 200 °C 12 minutos por lado, o freílas en aceite caliente 3 a 4 minutos por lado, hasta que estén doradas y cocidas en el centro.', 24, 'Horno 200 °C', NULL),
  (17, 5, 'Servir', 'Serví con gajos de limón y la guarnición que tengas: puré, ensalada o arroz.', NULL, NULL, NULL),
  (18, 1, 'Limpiar', 'Sacale al matambre el exceso de grasa, salpimentalo de ambos lados y untalo con el ajo picado.', NULL, NULL, NULL),
  (18, 2, 'Tiernizar en leche', 'Ponelo en una asadera con la grasa hacia abajo, cubrí con la leche y tapá con papel aluminio. Horneá a 180 °C durante 1 hora y media, hasta que al pincharlo esté muy tierno.', 90, 'Horno 180 °C', 'Tapado'),
  (18, 3, 'Dorar', 'Descartá la leche, dalo vuelta y subí el horno a 220 °C. Dorá 10 minutos.', 10, 'Horno 220 °C', NULL),
  (18, 4, 'Cubrir', 'Cubrí con el puré de tomate condimentado con sal y orégano, la muzzarella, las tiras de morrón y las aceitunas.', NULL, NULL, NULL),
  (18, 5, 'Gratinar', 'Volvé al horno 10 minutos hasta que el queso se derrita. Cortá en porciones y serví. Horno a 220 °C.', 10, 'Horno 220 °C', NULL),
  (19, 1, 'Cortar todo', 'Cortá las papas en rodajas de medio centímetro, la cebolla en aros, los morrones en tiras y los tomates en rodajas. Picá el ajo.', NULL, NULL, NULL),
  (19, 2, 'Primera capa', 'En una olla o cacerola amplia con un chorro de aceite, poné una capa de cebolla, arriba los bifes salpimentados y encima la mitad de los morrones y del tomate.', NULL, NULL, NULL),
  (19, 3, 'Segunda capa', 'Agregá una capa de papas, el resto de las verduras, el ajo, el laurel, el orégano y el pimentón. Salá cada capa.', NULL, NULL, NULL),
  (19, 4, 'Cocinar', 'Agregá medio vaso de caldo o agua, tapá y cociná a fuego bajo 40 minutos sin revolver, hasta que las papas estén tiernas.', 40, 'Fuego bajo', 'Tapado');
INSERT INTO "RecetaPasos" ("RecetaId", "Numero", "Titulo", "Descripcion", "Minutos", "Fuego", "Tapa") VALUES
  (19, 5, 'Servir', 'Serví directamente de la olla, con el jugo de la cocción por encima.', NULL, NULL, NULL),
  (20, 1, 'Dorar la carne', 'Cortá la carne en cubos de 3 cm, salpimentala, pasala por harina y dorala en tandas en una olla con aceite a fuego fuerte. Reservá. Sin tapa.', 12, 'Fuego fuerte', 'Destapado'),
  (20, 2, 'Sofrito', 'En la misma olla rehogá la cebolla, el morrón y el ajo picados 8 minutos. Sumá la zanahoria en rodajas y los champiñones fileteados. Hacelo a fuego medio y sin tapa.', 10, 'Fuego medio', 'Destapado'),
  (20, 3, 'Desglasar', 'Agregá el vino y raspá el fondo con cuchara de madera para despegar lo dorado. Dejá evaporar 3 minutos. Hacelo a fuego fuerte y sin tapa.', 3, 'Fuego fuerte', 'Destapado'),
  (20, 4, 'Cocinar a fuego lento', 'Volvé la carne, sumá el puré de tomate, el laurel, el orégano, el pimentón y el caldo disuelto en 500 ml de agua. Tapá y cociná a fuego bajo 1 hora.', 60, 'Fuego bajo', 'Tapado'),
  (20, 5, 'Agregar las papas', 'Sumá las papas en cubos grandes y cociná 25 minutos más, hasta que estén tiernas y la salsa espesa. Ajustá la sal y serví. Hacelo a fuego bajo, con la olla tapada.', 25, 'Fuego bajo', 'Tapado'),
  (21, 1, 'Hacer la mezcla', 'Remojá la miga de pan en la leche y escurrila. En un bowl uní la carne con la miga, el huevo, un diente de ajo y perejil picados, el queso, sal y pimienta. Amasá hasta integrar.', NULL, NULL, NULL),
  (21, 2, 'Formar', 'Con las manos húmedas formá bolitas del tamaño de una nuez grande. Si querés, pasalas por harina.', NULL, NULL, NULL),
  (21, 3, 'Dorar', 'Dorálas en una sartén con aceite a fuego medio, girándolas, unos 6 minutos. Reservá. Sin tapa.', 6, 'Fuego medio', 'Destapado'),
  (21, 4, 'Salsa', 'En una cacerola rehogá la cebolla y el ajo restante picados 8 minutos. Sumá el puré de tomate, medio vaso de agua, orégano y sal. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (21, 5, 'Cocinar juntas', 'Agregá las albóndigas a la salsa, tapá y cociná a fuego bajo 20 minutos, moviendo la olla de vez en cuando para que no se peguen.', 20, 'Fuego bajo', 'Tapado'),
  (22, 1, 'Preparar la carne', 'Mezclá la carne con la cebolla rallada y el ajo picado (y el huevo si querés que ligue más). No la amases de más; solo integrá.', NULL, NULL, NULL),
  (22, 2, 'Formar los medallones', 'Dividí en 4 bolas iguales y aplastalas hasta tener medallones de 1,5 cm un poco más anchos que el pan. Hacé un hueco con el pulgar en el centro.', NULL, NULL, NULL),
  (22, 3, 'Cocinar', 'Calentá bien una plancha o sartén con unas gotas de aceite. Salá los medallones justo antes de cocinarlos y hacelos 4 minutos por lado. En el último minuto poné el queso encima y tapá para que se derrita. Hacelo a fuego fuerte.', 8, 'Fuego fuerte', NULL),
  (22, 4, 'Armar', 'Tostá el pan en la misma plancha. Armá con lechuga, tomate, la hamburguesa y panceta crocante si tenés. Hacelo a fuego medio.', NULL, 'Fuego medio', NULL),
  (23, 1, 'Salsa criolla', 'Picá tomate, cebolla y morrón en cubitos chicos. Mezclalos con el vinagre, 4 cucharadas de aceite, orégano y sal. Dejala reposar mientras cocinás los chorizos.', 15, NULL, NULL),
  (23, 2, 'Cocinar los chorizos', 'Abrilos a lo largo sin separarlos del todo. Cocinalos en parrilla o en una plancha bien caliente unos 6 minutos de cada lado, empezando del lado de la piel. Hacelo a fuego medio-fuerte.', 12, 'Fuego medio-fuerte', NULL),
  (23, 3, 'Tostar el pan', 'Abrí los panes y tostalos del lado de adentro un minuto en la plancha. Hacelo a fuego medio.', 1, 'Fuego medio', NULL),
  (23, 4, 'Armar', 'Poné un chorizo en cada pan y coronalo con salsa criolla o chimichurri.', NULL, NULL, NULL),
  (24, 1, 'Enfriar', 'Espolvoreá las rodajas de provolone con orégano y llevalas al freezer 30 minutos.', 30, NULL, NULL),
  (24, 2, 'Primer lado', 'Calentá muy bien una sartén de hierro o una parrilla. Apoyá el queso y cociná 3 a 4 minutos sin tocarlo, hasta que se forme una costra dorada. Hacelo a fuego fuerte.', 4, 'Fuego fuerte', NULL),
  (24, 3, 'Dar vuelta', 'Girala con una espátula ancha y cociná 2 minutos más, hasta que el centro esté blando. Hacelo a fuego fuerte.', 2, 'Fuego fuerte', NULL),
  (24, 4, 'Servir', 'Serví al instante con rodajas de tomate, aceite de oliva, ají molido y pan para acompañar.', NULL, NULL, NULL),
  (25, 1, 'Activar la levadura', 'Disolvé la levadura y el azúcar en 300 ml de agua tibia. Dejá reposar 10 minutos hasta que espume.', 10, NULL, NULL),
  (25, 2, 'Amasar', 'En un bowl mezclá la harina con la sal, hacé un hueco y volcá la levadura y el aceite. Uní y amasá 10 minutos sobre la mesada hasta lograr una masa lisa y elástica.', 10, NULL, NULL),
  (25, 3, 'Leudar', 'Poné la masa en un bowl aceitado, tapala con film y dejala en un lugar cálido 1 hora, hasta que duplique su volumen.', 60, NULL, NULL),
  (25, 4, 'Estirar', 'Desgasificá la masa, dividila en 2 y estirala en pizzeras aceitadas. Dejala levar 15 minutos más.', 15, NULL, NULL),
  (25, 5, 'Prehornear', 'Mezclá el puré de tomate con sal, orégano y el ajo picado. Cubrí la masa con la salsa y horneá a 220 °C unos 12 minutos.', 12, 'Horno 220 °C', NULL),
  (25, 6, 'Gratinar', 'Agregá la muzzarella en cubos, volvé al horno 8 minutos hasta que se derrita, y terminá con orégano, un hilo de aceite y aceitunas. Horno a 220 °C.', 8, 'Horno 220 °C', NULL),
  (26, 1, 'Masa', 'Disolvé la levadura y el azúcar en 300 ml de agua tibia. Uní con la harina, la sal y 3 cucharadas de aceite y amasá 10 minutos. Dejá levar tapada 1 hora.', 70, NULL, NULL),
  (26, 2, 'Cebolla', 'Cortá la cebolla en pluma muy fina, salala y dejala 15 minutos. Escurrí el líquido que larga.', 15, NULL, NULL),
  (26, 3, 'Armar la base', 'Dividí la masa en 2 partes, una un poco más grande. Estirá la grande en una pizzera aceitada y cubrila con la muzzarella en fetas.', NULL, NULL, NULL),
  (26, 4, 'Cerrar', 'Estirá la otra parte, tapá la muzzarella y cerrá los bordes pellizcándolos. Distribuí la cebolla arriba, rociá con aceite y espolvoreá orégano y queso rallado.', NULL, NULL, NULL),
  (26, 5, 'Hornear', 'Horneá a 220 °C entre 25 y 30 minutos, hasta que la cebolla esté dorada y la masa cocida por debajo.', 30, 'Horno 220 °C', NULL),
  (27, 1, 'Cortar las verduras', 'Pelá y cortá todas las verduras en cubitos chicos y parejos para que se cocinen al mismo tiempo.', NULL, NULL, NULL),
  (27, 2, 'Rehogar', 'En una olla con un poco de aceite rehogá la cebolla, el puerro y el apio 5 minutos. Hacelo a fuego medio y sin tapa.', 5, 'Fuego medio', 'Destapado'),
  (27, 3, 'Hervir', 'Agregá el resto de las verduras, el caldo y 1,5 litros de agua. Cociná a fuego medio 25 minutos. Con la tapa apenas corrida.', 25, 'Fuego medio', 'Semitapado'),
  (27, 4, 'Fideos', 'Sumá los fideos y cociná el tiempo que indique el paquete (unos 5 minutos). Ajustá la sal. Hacelo a fuego medio y sin tapa.', 5, 'Fuego medio', 'Destapado'),
  (27, 5, 'Servir', 'Serví bien caliente con queso rallado por encima.', NULL, NULL, NULL),
  (28, 1, 'Hervir la carne', 'Poné la carne en una olla grande con 4 litros de agua fría, sal y laurel. Cuando hierva, retirá la espuma con una espumadera y cociná a fuego bajo 1 hora. Con la tapa apenas corrida.', 60, 'Fuego bajo', 'Semitapado'),
  (28, 2, 'Primeras verduras', 'Sumá la cebolla entera, el puerro, el apio, las zanahorias y los choclos en trozos. Si usás pollo y chorizo, agregalos ahora. Cociná 30 minutos. Hacelo a fuego bajo, con la tapa apenas corrida.', 30, 'Fuego bajo', 'Semitapado'),
  (28, 3, 'Últimas verduras', 'Agregá la papa, la batata y el zapallo en trozos grandes. Cociná 25 minutos más, hasta que todo esté tierno. Hacelo a fuego bajo, con la tapa apenas corrida.', 25, 'Fuego bajo', 'Semitapado'),
  (28, 4, 'Servir', 'Serví el caldo aparte como primer plato (podés hervir unos fideos en él) y después la carne con las verduras, con un chorrito de aceite de oliva y sal.', NULL, NULL, NULL),
  (29, 1, 'Cortar', 'Pelá las papas y las zanahorias y cortalas en cubitos de 1 cm.', NULL, NULL, NULL),
  (29, 2, 'Hervir', 'Ponelas en agua fría con sal y cociná 10 a 12 minutos desde que hierve, hasta que estén tiernas pero firmes. Escurrí y enfriá. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 12, 'Fuerte, después medio', 'Destapado'),
  (29, 3, 'Huevos duros', 'Hervé los huevos 10 minutos, enfrialos en agua fría, pelalos y picalos. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 10, 'Fuerte, después medio', 'Destapado'),
  (29, 4, 'Mezclar', 'Uní papa, zanahoria, arvejas escurridas y huevo. Agregá la mayonesa, unas gotas de limón y sal, y mezclá con suavidad. Enfriá en la heladera antes de servir.', NULL, NULL, NULL),
  (30, 1, 'Lavar', 'Lavá muy bien la lechuga hoja por hoja y secala con un repasador o centrifugador.', NULL, NULL, NULL),
  (30, 2, 'Cortar', 'Cortá la lechuga con las manos, el tomate en gajos y la cebolla en pluma fina. Si la cebolla es fuerte, dejala 5 minutos en agua fría.', 5, NULL, NULL),
  (30, 3, 'Condimentar', 'En un bowl mezclá todo, sumá zanahoria rallada y huevo duro si tenés, y condimentá con sal, aceite y vinagre al momento de servir.', NULL, NULL, NULL),
  (31, 1, 'Hervir', 'Hervé los zapallitos enteros 8 minutos en agua con sal. Escurrilos y dejalos enfriar. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 8, 'Fuerte, después medio', 'Destapado'),
  (31, 2, 'Vaciar', 'Cortalos a la mitad y retirá la pulpa con una cuchara, dejando un borde de medio centímetro. Picá la pulpa.', NULL, NULL, NULL),
  (31, 3, 'Relleno', 'Rehogá la cebolla y el morrón picados 8 minutos (si usás carne, sumala y cociná hasta que cambie de color). Agregá la pulpa y cociná 5 minutos más. Fuera del fuego sumá el huevo, el queso rallado, el cremoso en cubitos, sal, pimienta y nuez moscada. Hacelo a fuego medio y sin tapa.', 13, 'Fuego medio', 'Destapado'),
  (31, 4, 'Rellenar y gratinar', 'Rellená las mitades, espolvoreá pan rallado y queso, rociá con aceite y horneá a 200 °C 20 minutos hasta que estén dorados.', 20, 'Horno 200 °C', NULL),
  (32, 1, 'Rallar', 'Rallá los zapallitos con cáscara, salalos y dejalos 10 minutos en un colador. Apretalos para sacarles el agua.', 10, NULL, NULL),
  (32, 2, 'Rehogar', 'Rehogá la cebolla picada en aceite 8 minutos. Agregá los zapallitos y cociná 5 minutos más. Hacelo a fuego medio y sin tapa.', 13, 'Fuego medio', 'Destapado'),
  (32, 3, 'Mezclar', 'En un bowl batí los huevos con la leche, la harina, el queso rallado, sal y pimienta. Sumá las verduras y el cremoso en cubos.', NULL, NULL, NULL),
  (32, 4, 'Hornear', 'Volcá en una fuente aceitada y horneá a 180 °C unos 30 minutos, hasta que esté firme y dorado.', 30, 'Horno 180 °C', NULL),
  (33, 1, 'Tuco', 'Rehogá la cebolla y el ajo picados en aceite 8 minutos. Si usás carne, agregala y cociná hasta que cambie de color. Sumá el puré de tomate, laurel, orégano y sal, y cociná 20 minutos a fuego bajo. Con la tapa apenas corrida.', 28, 'Fuego bajo', 'Semitapado'),
  (33, 2, 'Hervir el líquido', 'En una olla llevá a hervor 1 litro de líquido (agua, o mitad agua y mitad leche para que quede más cremosa) con sal. Hacelo a fuego fuerte y sin tapa.', NULL, 'Fuego fuerte', 'Destapado'),
  (33, 3, 'Polenta', 'Bajá el fuego y echá la polenta en forma de lluvia mientras batís. Cociná revolviendo el tiempo que indique el paquete (de 1 a 5 minutos si es instantánea). Hacelo a fuego bajo y sin tapa.', 5, 'Fuego bajo', 'Destapado'),
  (33, 4, 'Terminar', 'Fuera del fuego, sumá la manteca, el queso rallado y el cremoso en cubos. Serví enseguida con el tuco por encima.', NULL, NULL, NULL),
  (34, 1, 'Dorar la carne', 'Si usás carne y chorizo, cortalos en cubos y rodajas y dorálos en una olla con aceite 8 minutos. Hacelo a fuego fuerte y sin tapa.', 8, 'Fuego fuerte', 'Destapado'),
  (34, 2, 'Sofrito', 'Agregá la cebolla y el morrón picados y rehogá 8 minutos. Sumá la zanahoria en rodajas y el pimentón. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (34, 3, 'Caldo', 'Incorporá el puré de tomate, el caldo y 1 litro de agua caliente. Cociná 15 minutos. Hacelo a fuego medio, con la olla tapada.', 15, 'Fuego medio', 'Tapado'),
  (34, 4, 'Arroz y papa', 'Agregá la papa en cubos y el arroz. Cociná 18 minutos revolviendo de vez en cuando. Al final sumá las arvejas y ajustá la sal. Hacelo a fuego bajo y sin tapa.', 18, 'Fuego bajo', 'Destapado'),
  (35, 1, 'Hervir', 'Cociná los fideos en abundante agua hirviendo con sal el tiempo que indica el paquete. Antes de escurrir, guardá una taza del agua de cocción. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (35, 2, 'Manteca', 'En la misma olla derretí la manteca a fuego bajo (con el ajo picado si te gusta, 1 minuto).', 1, 'Fuego bajo', NULL),
  (35, 3, 'Unir', 'Volvé los fideos, sumá el queso rallado y medio cucharón del agua de cocción. Revolvé enérgicamente hasta que se forme una salsa cremosa. Terminá con pimienta. Fuera del fuego.', NULL, 'Fuera del fuego', NULL),
  (36, 1, 'Hervir los fideos', 'Cociná los fideos en abundante agua con sal según el paquete. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (36, 2, 'Saltear', 'En una sartén con la manteca rehogá la cebolla picada 5 minutos. Sumá los champiñones fileteados y cociná hasta que se doren. Agregá el jamón en tiras. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (36, 3, 'Salsa', 'Incorporá la crema, sal, pimienta y nuez moscada. Cociná a fuego bajo 3 minutos, hasta que espese levemente. Sin tapa.', 3, 'Fuego bajo', 'Destapado'),
  (36, 4, 'Unir', 'Mezclá los fideos escurridos con la salsa y serví con queso rallado.', NULL, NULL, NULL),
  (37, 1, 'Panqueques', 'Licuá 150 g de harina, 350 ml de leche, 2 huevos, 20 g de manteca derretida y una pizca de sal. Dejá reposar 15 minutos y cociná panqueques finos en una sartén antiadherente enmantecada, 1 minuto por lado. Salen unos 10. Hacelo a fuego medio.', 30, 'Fuego medio', NULL),
  (37, 2, 'Relleno', 'Cociná la acelga, escurrila muy bien y picala. Rehogá la cebolla picada 8 minutos, sumá la acelga, y fuera del fuego mezclá con la ricota, 1 huevo, la mitad del queso, sal, pimienta y nuez moscada. Hacelo a fuego medio y sin tapa.', 15, 'Fuego medio', 'Destapado'),
  (37, 3, 'Salsa blanca', 'Derretí 40 g de manteca, agregá 40 g de harina y revolvé 1 minuto. Sumá 500 ml de leche de a poco batiendo y cociná hasta que espese. Condimentá con sal y nuez moscada. Hacelo a fuego medio-bajo y sin tapa.', 8, 'Fuego medio-bajo', 'Destapado'),
  (37, 4, 'Armar', 'Rellená cada panqueque, enrollalo y acomodalo en una fuente con un poco de tuco o salsa blanca en la base.', NULL, NULL, NULL),
  (37, 5, 'Gratinar', 'Cubrí con la salsa blanca, unas cucharadas de tuco y el resto del queso. Horneá a 200 °C 20 minutos hasta que estén dorados.', 20, 'Horno 200 °C', NULL),
  (38, 1, 'Rallar los choclos', 'Rallá los choclos con el rallador grueso sobre un bowl.', NULL, NULL, NULL),
  (38, 2, 'Sofrito', 'En una olla con manteca y aceite rehogá la cebolla y el morrón picados 10 minutos. Si usás zapallo, rallalo o cortalo en cubitos chicos y sumalo. Hacelo a fuego medio y sin tapa.', 10, 'Fuego medio', 'Destapado'),
  (38, 3, 'Cocinar el choclo', 'Agregá el choclo rallado, la leche, el azúcar, el pimentón, sal y pimienta. Cociná a fuego bajo revolviendo seguido 20 minutos, hasta que espese y esté cremoso. Sin tapa.', 20, 'Fuego bajo', 'Destapado'),
  (38, 4, 'Servir', 'Serví en cazuelas con cubos de queso cremoso por encima para que se derritan.', NULL, NULL, NULL),
  (39, 1, 'Remojar y hervir', 'Remojá los garbanzos 12 horas. Escurrilos y hervilos en agua sin sal 1 hora, hasta que estén tiernos. Hacelo a fuego bajo, con la tapa apenas corrida.', 60, 'Fuego bajo', 'Semitapado'),
  (39, 2, 'Sofrito', 'En otra olla dorá el chorizo y la panceta. Sumá la cebolla, el morrón y el ajo picados y rehogá 8 minutos. Agregá pimentón y comino. Hacelo a fuego medio y sin tapa.', 12, 'Fuego medio', 'Destapado'),
  (39, 3, 'Guisar', 'Incorporá el tomate triturado, la papa en cubos, los garbanzos escurridos y el caldo con 500 ml de agua. Cociná 20 minutos. Hacelo a fuego bajo, con la olla tapada.', 20, 'Fuego bajo', 'Tapado'),
  (39, 4, 'Espinaca', 'Si usás espinaca, sumala picada en los últimos 3 minutos. Ajustá la sal y serví. Hacelo a fuego bajo, con la olla tapada.', 3, 'Fuego bajo', 'Tapado'),
  (40, 1, 'Acelga', 'Cociná la acelga 3 minutos, escurrila muy bien y picala fina. Hacelo a fuego medio, con la olla tapada.', 3, 'Fuego medio', 'Tapado'),
  (40, 2, 'Pasta', 'En un bowl batí los huevos con la leche, el ajo picado, el queso, sal y pimienta. Sumá la harina leudante y mezclá hasta lograr una pasta espesa. Incorporá la acelga (y la cebolla picada si usás).', NULL, NULL, NULL),
  (40, 3, 'Freír', 'Con dos cucharas tomá porciones y freílas en aceite caliente a fuego medio, 2 minutos por lado, hasta que estén doradas. Sin tapa.', 10, 'Fuego medio', 'Destapado'),
  (40, 4, 'Escurrir', 'Escurrilos sobre papel absorbente y serví calientes, con ensalada o solos.', NULL, NULL, NULL),
  (41, 1, 'Papas', 'Pelá las papas, cortalas en bastones, lavalas y secalas muy bien. Freílas en aceite a fuego medio 8 minutos, retiralas, subí el fuego y freílas de nuevo 3 minutos hasta que estén doradas. Sin tapa.', 11, 'Medio, después fuerte', 'Destapado'),
  (41, 2, 'Bife', 'Calentá bien una plancha o sartén. Cociná los bifes 3 a 4 minutos por lado según el punto que te guste y salalos al final. Hacelo a fuego fuerte.', 8, 'Fuego fuerte', NULL),
  (41, 3, 'Huevo frito', 'Freí los huevos en aceite caliente, bañando la clara con el aceite con una cuchara, hasta que la clara esté cocida y la yema líquida. Hacelo a fuego medio-fuerte.', 2, 'Fuego medio-fuerte', NULL),
  (41, 4, 'Servir', 'Poné el huevo sobre el bife y acompañá con las papas fritas.', NULL, NULL, NULL),
  (42, 1, 'Mezcla', 'Mezclá la carne con los huevos, el pan rallado, la leche, la cebolla rallada, el ajo picado, sal, pimienta y nuez moscada.', NULL, NULL, NULL),
  (42, 2, 'Estirar', 'Sobre un papel manteca extendé la carne formando un rectángulo de 1,5 cm de espesor.', NULL, NULL, NULL),
  (42, 3, 'Rellenar', 'Cubrí con las fetas de jamón, el queso y tiras de morrón si tenés, dejando un borde libre.', NULL, NULL, NULL),
  (42, 4, 'Arrollar', 'Ayudándote con el papel, enrollá desde el lado más corto y cerrá bien los extremos.', NULL, NULL, NULL),
  (42, 5, 'Hornear', 'Pasalo a una asadera aceitada y horneá a 190 °C durante 45 minutos. Dejá reposar 10 minutos antes de cortar en rodajas.', 45, 'Horno 190 °C', NULL),
  (43, 1, 'Asar el zapallo', 'Cortá el zapallo a lo largo, retirá las semillas, pincelalo con aceite y sal, y horneá boca abajo a 200 °C unos 40 minutos, hasta que esté tierno.', 40, 'Horno 200 °C', NULL);
INSERT INTO "RecetaPasos" ("RecetaId", "Numero", "Titulo", "Descripcion", "Minutos", "Fuego", "Tapa") VALUES
  (43, 2, 'Relleno', 'Rehogá la cebolla picada 8 minutos, sumá los granos de choclo y la crema y cociná 5 minutos. Condimentá con sal, pimienta y nuez moscada. Hacelo a fuego medio y sin tapa.', 13, 'Fuego medio', 'Destapado'),
  (43, 3, 'Rellenar', 'Retirá parte de la pulpa del zapallo con una cuchara, pisala y mezclala con el relleno y el cremoso en cubos. Rellená las mitades.', NULL, NULL, NULL),
  (43, 4, 'Gratinar', 'Cubrí con queso rallado y gratiná 10 minutos a horno fuerte. Horno a 220 °C.', 10, 'Horno 220 °C', NULL),
  (44, 1, 'Preparar el pescado', 'Secá los filets con papel, quitales espinas si tienen, salpimentalos y rociá con unas gotas de limón.', NULL, NULL, NULL),
  (44, 2, 'Masa', 'Batí los huevos con la leche, sumá la harina, el polvo de hornear y una pizca de sal hasta lograr una masa lisa, como de panqueque espeso.', NULL, NULL, NULL),
  (44, 3, 'Rebozar y freír', 'Pasá cada filet por harina, después por la masa, y freílo en aceite caliente 3 minutos por lado hasta que esté dorado. Hacelo a fuego medio-fuerte y sin tapa.', 6, 'Fuego medio-fuerte', 'Destapado'),
  (44, 4, 'Servir', 'Escurrí sobre papel y serví con gajos de limón, perejil picado y ensalada o puré.', NULL, NULL, NULL),
  (45, 1, 'Arroz', 'Hervé el arroz en abundante agua con sal 15 minutos. Escurrilo y pasalo por agua fría. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 15, 'Fuerte, después medio', 'Destapado'),
  (45, 2, 'Huevos', 'Hervé los huevos 10 minutos, enfrialos y picalos. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 10, 'Fuerte, después medio', 'Destapado'),
  (45, 3, 'Mezclar', 'En un bowl grande uní el arroz con el atún desmenuzado, el tomate y el morrón en cubitos, los granos de choclo, las arvejas y el huevo.', NULL, NULL, NULL),
  (45, 4, 'Condimentar', 'Condimentá con aceite, limón y sal, o con mayonesa si la preferís más cremosa. Enfriá antes de servir.', NULL, NULL, NULL),
  (46, 1, 'Dorar el pollo', 'Cortá las pechugas en cubos, salpimentalas y dorálas en una sartén con aceite a fuego fuerte 6 minutos. Retirá. Sin tapa.', 6, 'Fuego fuerte', 'Destapado'),
  (46, 2, 'Verdeo', 'En la misma sartén derretí la manteca y rehogá la parte blanca del verdeo picada 4 minutos. Hacelo a fuego medio-bajo y sin tapa.', 4, 'Fuego medio-bajo', 'Destapado'),
  (46, 3, 'Salsa', 'Agregá la crema (y medio cubo de caldo desgranado si querés más sabor) y cociná 3 minutos a fuego bajo. Sin tapa.', 3, 'Fuego bajo', 'Destapado'),
  (46, 4, 'Unir', 'Volvé el pollo, sumá la parte verde del verdeo y cociná 3 minutos más. Serví con arroz blanco o puré y queso rallado por encima. Hacelo a fuego bajo y sin tapa.', 3, 'Fuego bajo', 'Destapado'),
  (47, 1, 'Rehogar', 'Rehogá la cebolla en pluma (y el ajo) en una sartén con aceite 5 minutos. Hacelo a fuego medio y sin tapa.', 5, 'Fuego medio', 'Destapado'),
  (47, 2, 'Zapallitos', 'Sumá los zapallitos en cubitos, salá y cociná a fuego medio-fuerte 8 minutos, hasta que estén tiernos y un poco dorados. Sin tapa.', 8, 'Fuego medio-fuerte', 'Destapado'),
  (47, 3, 'Huevo', 'Bajá el fuego, agregá los huevos batidos con el queso, sal y pimienta, y revolvé hasta que cuajen pero sigan húmedos. Hacelo a fuego bajo y sin tapa.', 2, 'Fuego bajo', 'Destapado'),
  (48, 1, 'Dorar', 'Si usás carne, cortala en cubos chicos y dorala en una olla con aceite 8 minutos. Hacelo a fuego fuerte y sin tapa.', 8, 'Fuego fuerte', 'Destapado'),
  (48, 2, 'Sofrito', 'Sumá la cebolla y el morrón picados y rehogá 8 minutos. Agregá la zanahoria en rodajas, el pimentón y el laurel. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (48, 3, 'Caldo', 'Incorporá el puré de tomate, el caldo y 1,2 litros de agua caliente. Cociná 15 minutos. Hacelo a fuego medio, con la olla tapada.', 15, 'Fuego medio', 'Tapado'),
  (48, 4, 'Fideos', 'Sumá la papa en cubos y los fideos y cociná revolviendo seguido hasta que estén al dente, unos 12 minutos. Si se espesa demasiado, agregá agua caliente. Hacelo a fuego medio y sin tapa.', 12, 'Fuego medio', 'Destapado'),
  (49, 1, 'Choclo', 'Desgraná los choclos (o escurrí el de lata). Si son frescos, hervilos 8 minutos antes. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 8, 'Fuerte, después medio', 'Destapado'),
  (49, 2, 'Sofrito', 'Rehogá la cebolla y el morrón picados en aceite 8 minutos. Sumá el choclo. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (49, 3, 'Salsa blanca', 'En otra olla derretí la manteca, sumá la harina, revolvé 1 minuto y agregá la leche de a poco batiendo hasta que espese. Condimentá con sal, pimienta y nuez moscada. Hacelo a fuego medio-bajo y sin tapa.', 6, 'Fuego medio-bajo', 'Destapado'),
  (49, 4, 'Relleno', 'Uní el choclo con la salsa blanca. Cuando esté tibio, agregá los huevos batidos y el queso en cubos.', NULL, NULL, NULL),
  (49, 5, 'Hornear', 'Forrá una tartera con una tapa, rellená, cubrí con la otra y cerrá. Horneá a 200 °C 35 minutos.', 35, 'Horno 200 °C', NULL),
  (50, 1, 'Desamargar', 'Cortá las berenjenas en rodajas de 1 cm, salalas y dejalas en un colador 20 minutos. Secalas bien con papel.', 20, NULL, NULL),
  (50, 2, 'Empanar', 'Batí los huevos con ajo picado, queso rallado, sal y pimienta. Pasá cada rodaja por el huevo y por pan rallado.', NULL, NULL, NULL),
  (50, 3, 'Hornear', 'Acomodalas en una placa aceitada, rociá con aceite y horneá a 200 °C 12 minutos por lado.', 24, 'Horno 200 °C', NULL),
  (50, 4, 'Opcional: napolitana', 'Cubrilas con salsa de tomate, muzzarella y orégano, y gratiná 5 minutos más. Horno a 220 °C.', 5, 'Horno 220 °C', NULL),
  (51, 1, 'Dorar', 'Salpimentá las presas y dorálas en una cacerola con aceite 5 minutos por lado. Retirá. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (51, 2, 'Verduras', 'Rehogá la cebolla en pluma, los morrones en tiras y el ajo 10 minutos. Sumá los tomates en cubos y el pimentón. Hacelo a fuego medio y sin tapa.', 10, 'Fuego medio', 'Destapado'),
  (51, 3, 'Guisar', 'Agregá el vino y dejá evaporar 2 minutos. Volvé el pollo, sumá el puré de tomate, el laurel y medio vaso de agua. Tapá y cociná a fuego bajo 30 minutos.', 32, 'Fuego bajo', 'Tapado'),
  (51, 4, 'Terminar', 'Agregá las aceitunas, ajustá la sal y cociná 5 minutos destapado para que espese la salsa. Hacelo a fuego medio.', 5, 'Fuego medio', 'Destapado'),
  (52, 1, 'Cocinar las lentejas', 'Hervé las lentejas en agua sin sal 25 minutos, hasta que estén tiernas. Escurrilas muy bien. Hacelo a fuego medio y sin tapa.', 25, 'Fuego medio', 'Destapado'),
  (52, 2, 'Sofrito', 'Rehogá la cebolla picada, la zanahoria rallada y el ajo en aceite 8 minutos. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (52, 3, 'Procesar', 'Pisá las lentejas con un tenedor o procesalas brevemente (que queden algunas enteras). Mezclá con el sofrito, el huevo, el pan rallado, comino, pimentón, perejil, sal y pimienta.', NULL, NULL, NULL),
  (52, 4, 'Formar y cocinar', 'Formá 6 medallones y cocinalos en una sartén con aceite 4 minutos por lado, o al horno a 200 °C 15 minutos por lado. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (53, 1, 'Hervir el pollo', 'Hervé las pechugas en agua con sal 20 minutos. Dejalas enfriar y desmenuzalas. Hacelo a fuego medio, con la tapa apenas corrida.', 20, 'Fuego medio', 'Semitapado'),
  (53, 2, 'Papas y huevos', 'Hervé las papas en cubos 12 minutos y los huevos 10 minutos. Enfriá y picá los huevos. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 12, 'Fuerte, después medio', 'Destapado'),
  (53, 3, 'Cortar', 'Cortá el tomate, el morrón y la cebolla en cubitos.', NULL, NULL, NULL),
  (53, 4, 'Mezclar', 'Uní todo en una fuente, condimentá con aceite, vinagre o limón y sal (o con mayonesa). Serví frío sobre hojas de lechuga.', NULL, NULL, NULL),
  (54, 1, 'Hervir el zapallo', 'Pelá el zapallo, cortalo en cubos y hervilo 15 minutos (o cocinalo al vapor), hasta que esté tierno. Hacelo a fuego medio, con la olla tapada.', 15, 'Fuego medio', 'Tapado'),
  (54, 2, 'Puré', 'Escurrilo muy bien y pisalo con la manteca, sal, pimienta y nuez moscada. Si queda espeso, agregá un chorrito de leche.', NULL, NULL, NULL),
  (54, 3, 'Bife', 'Cociná los bifes en una plancha bien caliente con unas gotas de aceite, 3 a 4 minutos por lado. Salá al final y dejalos reposar 3 minutos. Hacelo a fuego fuerte.', 8, 'Fuego fuerte', NULL),
  (55, 1, 'Zapallitos', 'Rallá los zapallitos, salalos y dejalos 10 minutos en un colador. Apretalos para sacar el agua.', 10, NULL, NULL),
  (55, 2, 'Rehogar', 'Rehogá la cebolla picada 8 minutos, sumá los zapallitos y cociná 5 minutos más. Dejá entibiar. Hacelo a fuego medio y sin tapa.', 13, 'Fuego medio', 'Destapado'),
  (55, 3, 'Relleno', 'Batí los huevos con la crema, sal y pimienta. Sumá la verdura y el cremoso en cubos.', NULL, NULL, NULL),
  (55, 4, 'Hornear', 'Forrá una tartera con la tapa, rellená, cubrí con queso rallado y horneá a 200 °C 30 minutos, hasta que esté firme y dorada.', 30, 'Horno 200 °C', NULL),
  (56, 1, 'Condimentar', 'Sacá el vacío de la heladera 30 minutos antes. Salalo con sal gruesa de ambos lados y untalo con ajo picado.', 30, NULL, NULL),
  (56, 2, 'Primera cocción tapado', 'Ponelo en una asadera con la grasa hacia arriba, cubrí con papel aluminio y horneá a 170 °C durante 1 hora y 15 minutos. Tapado con papel aluminio.', 75, 'Horno 170 °C', 'Tapado'),
  (56, 3, 'Sumar las papas', 'Destapá, agregá las papas en gajos con aceite, sal y romero alrededor de la carne y subí el horno a 200 °C.', NULL, NULL, NULL),
  (56, 4, 'Dorar', 'Cociná 40 minutos más, dando vuelta las papas a mitad de camino, hasta que el vacío esté dorado y las papas crocantes. Horno a 200 °C. Sin tapar.', 40, 'Horno 200 °C', 'Destapado'),
  (56, 5, 'Reposar y servir', 'Dejá reposar la carne 10 minutos antes de cortarla en tiras contra la fibra. Serví con chimichurri.', 10, NULL, NULL),
  (57, 1, 'Preparar', 'Precalentá el horno a 200 °C. Salá el asado con sal gruesa de ambos lados.', NULL, NULL, NULL),
  (57, 2, 'Hueso abajo', 'Acomodá las tiras en una asadera con el hueso hacia abajo y horneá 40 minutos sin abrir el horno. Horno a 200 °C.', 40, 'Horno 200 °C', NULL),
  (57, 3, 'Dar vuelta', 'Girá las tiras y cociná 30 a 40 minutos más, hasta que la grasa esté dorada y crocante. Horno a 200 °C.', 35, 'Horno 200 °C', NULL),
  (57, 4, 'Servir', 'Cortá entre los huesos y serví con chimichurri, unas gotas de limón y una ensalada de lechuga y tomate.', NULL, NULL, NULL),
  (58, 1, 'Papas', 'Cortá las papas con cáscara en gajos, mezclalas con aceite, sal y provenzal y horneá a 220 °C unos 35 minutos, moviéndolas a mitad de cocción.', 35, 'Horno 220 °C', NULL),
  (58, 2, 'Limpiar la entraña', 'Si tiene la membrana blanca, retirala con un cuchillo. Secala bien con papel.', NULL, NULL, NULL),
  (58, 3, 'Sellar', 'Calentá muy bien una plancha o sartén de hierro. Cociná la entraña 4 minutos por lado sin moverla. Salá al final. Hacelo a fuego fuerte.', 8, 'Fuego fuerte', NULL),
  (58, 4, 'Servir', 'Dejala reposar 3 minutos, cortala en tiras contra la fibra y serví con las papas y chimichurri.', NULL, NULL, NULL),
  (59, 1, 'Sellar', 'Salpimentá la colita y dorála en una sartén bien caliente con aceite, 3 minutos por cada lado. Hacelo a fuego fuerte y sin tapa.', 12, 'Fuego fuerte', 'Destapado'),
  (59, 2, 'Verduras', 'Cortá el zapallo, las batatas, la cebolla y el morrón en trozos grandes. Acomodalos en una asadera con aceite, sal, ajo y romero.', NULL, NULL, NULL),
  (59, 3, 'Hornear', 'Poné la carne encima, rociá con el vino y horneá a 200 °C entre 40 y 50 minutos, según el punto que te guste.', 45, 'Horno 200 °C', NULL),
  (59, 4, 'Reposar', 'Dejá reposar la carne 10 minutos tapada con aluminio y cortala en rodajas finas. Serví con las verduras.', 10, NULL, NULL),
  (60, 1, 'Sellar', 'Salpimentá los medallones y sellalos en una sartén muy caliente con aceite, 2 o 3 minutos por lado. Retirá y reservá. Hacelo a fuego fuerte y sin tapa.', 6, 'Fuego fuerte', 'Destapado'),
  (60, 2, 'Champiñones', 'En la misma sartén derretí la manteca, rehogá la cebolla picada 4 minutos y sumá los champiñones fileteados hasta que se doren. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (60, 3, 'Salsa', 'Agregá el vino y dejá evaporar 2 minutos. Incorporá la crema, sal y pimienta y cociná hasta que espese levemente. Hacelo a fuego medio y sin tapa.', 5, 'Fuego medio', 'Destapado'),
  (60, 4, 'Terminar', 'Volvé los medallones a la salsa 1 minuto por lado. Serví con papas al natural o puré. Hacelo a fuego medio y sin tapa.', 2, 'Fuego medio', 'Destapado'),
  (61, 1, 'Dorar', 'Salpimentá la bondiola, untala con la mostaza y dorála de todos lados en una olla con aceite. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (61, 2, 'Cebollas', 'Retirá la carne, rehogá las cebollas en pluma en la misma olla 10 minutos hasta que estén doradas. Hacelo a fuego medio y sin tapa.', 10, 'Fuego medio', 'Destapado'),
  (61, 3, 'Brasear', 'Volvé la bondiola, agregá la cerveza, la miel y las ciruelas. Tapá y cociná a fuego bajo 2 horas, girándola cada tanto. También podés hacerlo en el horno a 170 °C.', 120, 'Fuego bajo', 'Tapado'),
  (61, 4, 'Salsa y servir', 'Retirá la carne, reducí la salsa 5 minutos a fuego fuerte y serví la bondiola en rodajas bañada con la salsa, con batatas al horno. Sin tapa.', 5, 'Fuego fuerte', 'Destapado'),
  (62, 1, 'Puré', 'Hervé las papas y las manzanas peladas en cubos 20 minutos. Escurrí y pisá con la manteca, la leche y sal. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 20, 'Fuerte, después medio', 'Destapado'),
  (62, 2, 'Bifes', 'Salpimentá los bifes. Cocinalos en una sartén caliente con aceite y romero, 4 minutos por lado. Hacelo a fuego medio-fuerte.', 8, 'Fuego medio-fuerte', NULL),
  (62, 3, 'Servir', 'Dejá reposar 2 minutos y serví con el puré.', NULL, NULL, NULL),
  (63, 1, 'Condimentar', 'Frotá las costillitas con sal, pimienta, pimentón y ajo picado.', NULL, NULL, NULL),
  (63, 2, 'Cocción lenta', 'Envolvelas en papel aluminio y horneá a 160 °C durante 1 hora y 45 minutos, hasta que la carne se separe del hueso. Tapado con papel aluminio.', 105, 'Horno 160 °C', 'Tapado'),
  (63, 3, 'Glasear', 'Abrí el papel, pincelá con la salsa barbacoa mezclada con la miel y subí el horno a 220 °C.', NULL, NULL, NULL),
  (63, 4, 'Dorar', 'Horneá 15 minutos más, pincelando una vez más a mitad de camino. Cortá entre los huesos y serví. Horno a 220 °C. Sin tapar.', 15, 'Horno 220 °C', 'Destapado'),
  (64, 1, 'Marinar', 'Mezclá el jugo de los limones con ajo picado, orégano, sal, pimienta y aceite. Cubrí el matambrito y dejalo 30 minutos.', 30, NULL, NULL),
  (64, 2, 'Hornear tapado', 'Ponelo en una asadera con la marinada, tapá con aluminio y horneá a 180 °C durante 40 minutos.', 40, 'Horno 180 °C', 'Tapado'),
  (64, 3, 'Dorar', 'Destapá, sumá las papas en rodajas alrededor y horneá 30 minutos más a 200 °C hasta que todo esté dorado.', 30, 'Horno 200 °C', 'Destapado'),
  (65, 1, 'Remojar', 'Cortá el hígado en bifes finos, retirá las partes duras y dejalo en leche 30 minutos (reservá 100 ml de leche para el puré).', 30, NULL, NULL),
  (65, 2, 'Puré', 'Hervé las papas 20 minutos, escurrí y pisá con manteca, leche y sal. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 20, 'Fuerte, después medio', 'Destapado'),
  (65, 3, 'Cebollas', 'Rehogá las cebollas en pluma con aceite a fuego medio 15 minutos, hasta que estén doradas. Retirá. Sin tapa.', 15, 'Fuego medio', 'Destapado'),
  (65, 4, 'Hígado', 'Secá los bifes, pasalos apenas por harina y cocinalos en la sartén caliente 2 minutos por lado. Salpimentá, volvé las cebollas y serví con el puré. Hacelo a fuego fuerte y sin tapa.', 4, 'Fuego fuerte', 'Destapado'),
  (66, 1, 'Limpiar', 'Lavá el mondongo frotándolo con limón y sal. Enjuagalo varias veces.', NULL, NULL, NULL),
  (66, 2, 'Hervir', 'Hervilo en abundante agua con laurel durante 1 hora y media, hasta que esté tierno. En otra olla cociná los garbanzos 1 hora. Hacelo a fuego medio, con la tapa apenas corrida.', 90, 'Fuego medio', 'Semitapado'),
  (66, 3, 'Sofrito', 'Cortá el mondongo en tiras. En una cacerola dorá el chorizo en rodajas, sumá cebolla, morrón y ajo picados y rehogá 8 minutos. Agregá el pimentón. Hacelo a fuego medio y sin tapa.', 12, 'Fuego medio', 'Destapado'),
  (66, 4, 'Guisar', 'Incorporá el mondongo, los garbanzos, el puré de tomate y un vaso de agua. Cociná 40 minutos a fuego bajo (sumá las papas en cubos en los últimos 20). Con la olla tapada.', 40, 'Fuego bajo', 'Tapado'),
  (67, 1, 'Hervir', 'Poné la lengua en una olla con agua, una cebolla, la zanahoria, laurel y sal. Cociná 2 horas y media a fuego bajo, hasta que esté tierna. Con la olla tapada.', 150, 'Fuego bajo', 'Tapado'),
  (67, 2, 'Pelar', 'Retirala y pelala enseguida, en caliente. Dejala enfriar y cortala en fetas finas.', NULL, NULL, NULL),
  (67, 3, 'Vinagreta', 'Picá muy chico la otra cebolla, los morrones, el ajo, el perejil y los huevos duros. Mezclá con el aceite, el vinagre, sal y pimienta.', NULL, NULL, NULL),
  (67, 4, 'Armar', 'Acomodá las fetas en una fuente, cubrí con la vinagreta y dejá en la heladera al menos 2 horas antes de servir.', 120, NULL, NULL),
  (68, 1, 'Preparar', 'Hacé cortes en la carne y metele ajo y romero. Untala con aceite, sal, pimienta y jugo de limón.', NULL, NULL, NULL),
  (68, 2, 'Hornear tapado', 'Ponela en una asadera con el vino, tapá con aluminio y horneá a 170 °C durante 1 hora y 15 minutos.', 75, 'Horno 170 °C', 'Tapado'),
  (68, 3, 'Papas', 'Destapá, agregá las papas en gajos con aceite y sal, y subí a 200 °C.', NULL, NULL, NULL);
INSERT INTO "RecetaPasos" ("RecetaId", "Numero", "Titulo", "Descripcion", "Minutos", "Fuego", "Tapa") VALUES
  (68, 4, 'Dorar', 'Cociná 45 minutos más, bañando la carne con sus jugos cada tanto, hasta que esté dorada. Horno a 200 °C. Sin tapar.', 45, 'Horno 200 °C', 'Destapado'),
  (69, 1, 'Relleno', 'Rehogá una cebolla picada, sumá la carne y cociná hasta que pierda el color. Condimentá con comino, pimentón, sal y pimienta. Hacelo a fuego medio y sin tapa.', 15, 'Fuego medio', 'Destapado'),
  (69, 2, 'Crema de choclo', 'Rallá los choclos. Rehogá la otra cebolla en la manteca, agregá el choclo, la leche y albahaca, y cociná revolviendo 15 minutos hasta que espese. Hacelo a fuego medio-bajo y sin tapa.', 20, 'Fuego medio-bajo', 'Destapado'),
  (69, 3, 'Armar', 'En una fuente poné la carne, distribuí el huevo duro picado, las aceitunas y las pasas, y cubrí con la crema de choclo.', NULL, NULL, NULL),
  (69, 4, 'Gratinar', 'Espolvoreá azúcar y horneá a 200 °C unos 25 minutos, hasta que esté dorado.', 25, 'Horno 200 °C', NULL),
  (70, 1, 'Milanesas', 'Pasá la carne por un huevo batido con sal y luego por pan rallado. Freílas o horneálas a 200 °C 10 minutos por lado.', 20, 'Horno 200 °C', NULL),
  (70, 2, 'Huevos', 'Freí los otros dos huevos en una sartén con aceite. Hacelo a fuego medio.', 3, 'Fuego medio', NULL),
  (70, 3, 'Armar', 'Abrí los panes, untá con mayonesa y armá con lechuga, tomate, la milanesa, jamón, queso y el huevo frito.', NULL, NULL, NULL),
  (71, 1, 'Bifes', 'Aplaná los bifes de lomo y cocinalos en una plancha bien caliente 1 minuto por lado. Salpimentá. Hacelo a fuego fuerte.', 2, 'Fuego fuerte', NULL),
  (71, 2, 'Queso', 'Poné el jamón y el queso sobre la carne en la plancha y tapá hasta que se derrita. Hacelo a fuego medio.', 2, 'Fuego medio', 'Tapado'),
  (71, 3, 'Huevo', 'Freí los huevos a la plancha. Hacelo a fuego medio.', 3, 'Fuego medio', NULL),
  (71, 4, 'Armar', 'Tostá el pan, untá con mayonesa y armá con lechuga, tomate, el lomo con jamón y queso y el huevo.', NULL, NULL, NULL),
  (72, 1, 'Calentar', 'Poné las salchichas en agua caliente sin que llegue a hervir fuerte, 5 minutos. Hacelo a fuego bajo y sin tapa.', 5, 'Fuego bajo', 'Destapado'),
  (72, 2, 'Pan', 'Calentá los panes 1 minuto en el horno o en una sartén. Hacelo a fuego medio.', 1, 'Fuego medio', NULL),
  (72, 3, 'Armar', 'Poné cada salchicha en un pan y sumá mostaza, kétchup, mayonesa o pepinillos picados.', NULL, NULL, NULL),
  (73, 1, 'Salsa criolla', 'Si querés, picá tomate y cebolla y condimentá con vinagre, aceite y sal.', NULL, NULL, NULL),
  (73, 2, 'Morcilla', 'Cociná las morcillas enteras en una plancha a fuego medio 8 minutos por lado.', 16, 'Fuego medio', NULL),
  (73, 3, 'Armar', 'Abrí los panes, tostalos y armá con la morcilla y la salsa criolla o chimichurri.', NULL, NULL, NULL),
  (74, 1, 'Puré', 'Hervé las papas en cubos 20 minutos, escurrí y pisá con manteca, leche, sal y nuez moscada. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 20, 'Fuerte, después medio', 'Destapado'),
  (74, 2, 'Salchichas', 'Calentá las salchichas en agua 4 minutos y después dorálas en una sartén con un poco de manteca. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (74, 3, 'Servir', 'Serví con el puré y mostaza.', NULL, NULL, NULL),
  (75, 1, 'Sofrito', 'Rehogá la cebolla, el morrón, el ajo y el ají picados en aceite 8 minutos. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (75, 2, 'Carne', 'Sumá la carne y cociná hasta que se dore. Agregá comino y pimentón. Hacelo a fuego medio-fuerte y sin tapa.', 8, 'Fuego medio-fuerte', 'Destapado'),
  (75, 3, 'Guisar', 'Incorporá el tomate y los porotos cocidos. Cociná tapado a fuego bajo 30 minutos, revolviendo de vez en cuando.', 30, 'Fuego bajo', 'Tapado'),
  (75, 4, 'Servir', 'Ajustá sal y picante y serví con arroz blanco.', NULL, NULL, NULL),
  (76, 1, 'Relleno', 'Rehogá la cebolla picada, sumá la carne y cocinala con comino, pimentón y sal. Agregá los porotos y un tomate picado y cociná 10 minutos. Hacelo a fuego medio y sin tapa.', 20, 'Fuego medio', 'Destapado'),
  (76, 2, 'Arroz', 'Si usás arroz, hervilo 15 minutos y escurrilo. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 15, 'Fuerte, después medio', 'Destapado'),
  (76, 3, 'Armar', 'Calentá las tortillas. Rellená con arroz, carne, queso rallado, tomate y palta. Doblá los costados y enrollá.', NULL, NULL, NULL),
  (76, 4, 'Dorar', 'Dorálos en una sartén 2 minutos por lado para que el queso se derrita. Hacelo a fuego medio.', 4, 'Fuego medio', NULL),
  (77, 1, 'Pollo', 'Hervé las pechugas 20 minutos en agua con sal. Desmenuzalas. Hacelo a fuego medio, con la tapa apenas corrida.', 20, 'Fuego medio', 'Semitapado'),
  (77, 2, 'Relleno', 'Rehogá cebolla, morrón y verdeo picados 10 minutos. Sumá el pollo, pimentón, comino, sal y un chorrito de caldo. Dejá enfriar. Hacelo a fuego medio y sin tapa.', 10, 'Fuego medio', 'Destapado'),
  (77, 3, 'Armar', 'Rellená las tapas, agregá huevo duro picado, cerrá con repulgue y pintá con huevo batido.', NULL, NULL, NULL),
  (77, 4, 'Hornear', 'Horneá a 220 °C entre 15 y 18 minutos hasta que estén doradas.', 18, 'Horno 220 °C', NULL),
  (78, 1, 'Relleno', 'Cortá el jamón y la muzzarella en cubitos. Mezclá con orégano.', NULL, NULL, NULL),
  (78, 2, 'Armar', 'Rellená las tapas, cerrá con repulgue o tenedor y pintá con huevo.', NULL, NULL, NULL),
  (78, 3, 'Hornear', 'Horneá a 220 °C unos 12 minutos o freílas en aceite caliente.', 12, 'Horno 220 °C', NULL),
  (79, 1, 'Choclo', 'Rallá o desgraná los choclos. Rehogá la cebolla en la manteca 5 minutos y sumá el choclo. Hacelo a fuego medio y sin tapa.', 10, 'Fuego medio', 'Destapado'),
  (79, 2, 'Salsa', 'Agregá la harina, revolvé y sumá la leche de a poco hasta que espese. Condimentá con sal, nuez moscada y azúcar. Dejá enfriar. Hacelo a fuego medio-bajo y sin tapa.', 8, 'Fuego medio-bajo', 'Destapado'),
  (79, 3, 'Armar', 'Rellená las tapas con la humita y un cubo de queso. Cerrá y pintá con huevo.', NULL, NULL, NULL),
  (79, 4, 'Hornear', 'Horneá a 220 °C unos 15 minutos.', 15, 'Horno 220 °C', NULL),
  (80, 1, 'Relleno crudo', 'Mezclá la carne con el tomate y la cebolla picados muy chico, el jugo de los limones, perejil, sal, pimienta y ají. Dejá reposar 15 minutos y escurrí el líquido.', 15, NULL, NULL),
  (80, 2, 'Armar', 'Poné relleno en el centro de cada tapa y cerrá en forma de triángulo, pellizcando los tres bordes.', NULL, NULL, NULL),
  (80, 3, 'Hornear', 'Horneá a 220 °C unos 18 minutos.', 18, 'Horno 220 °C', NULL),
  (81, 1, 'Pollo', 'Hervé o cociná a la plancha las pechugas y desmenuzalas. Hacelo a fuego medio, con la tapa apenas corrida.', 20, 'Fuego medio', 'Semitapado'),
  (81, 2, 'Relleno', 'Rehogá la cebolla y el morrón 10 minutos, sumá el pollo y condimentá. Fuera del fuego agregá la crema, los huevos y el queso. Hacelo a fuego medio y sin tapa.', 10, 'Fuego medio', 'Destapado'),
  (81, 3, 'Hornear', 'Forrá una tartera con una tapa, rellená, tapá con la otra y horneá a 200 °C 35 minutos.', 35, 'Horno 200 °C', NULL),
  (82, 1, 'Sofrito', 'Rehogá la cebolla y el morrón picados 8 minutos. Sumá el tomate en cubos y cociná 5 minutos. Hacelo a fuego medio y sin tapa.', 13, 'Fuego medio', 'Destapado'),
  (82, 2, 'Relleno', 'Fuera del fuego mezclá con el atún escurrido, las aceitunas y 2 huevos batidos.', NULL, NULL, NULL),
  (82, 3, 'Hornear', 'Rellená la tartera forrada con una tapa, cubrí con la otra, pintá con el huevo restante y horneá a 200 °C 30 minutos.', 30, 'Horno 200 °C', NULL),
  (83, 1, 'Puerros', 'Cortá los puerros en rodajas finas y rehogalos en la manteca a fuego bajo 12 minutos, hasta que estén tiernos. Sin tapa.', 12, 'Fuego bajo', 'Destapado'),
  (83, 2, 'Relleno', 'Batí los huevos con la crema, sal, pimienta y nuez moscada. Sumá los puerros y los quesos.', NULL, NULL, NULL),
  (83, 3, 'Hornear', 'Volcá sobre la masa en una tartera y horneá a 190 °C 30 minutos, hasta que esté firme y dorada.', 30, 'Horno 190 °C', NULL),
  (84, 1, 'Calabaza', 'Horneá la calabaza en cubos con aceite y sal a 200 °C 30 minutos. Pisala.', 30, 'Horno 200 °C', NULL),
  (84, 2, 'Relleno', 'Rehogá la cebolla picada y mezclala con la calabaza, los huevos, el queso rallado, nuez moscada y el cremoso en cubos. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (84, 3, 'Hornear', 'Rellená la tartera forrada, tapá con la otra masa y horneá a 200 °C 30 minutos.', 30, 'Horno 200 °C', NULL),
  (85, 1, 'Brócoli', 'Separá el brócoli en ramitos y hervilo 3 minutos. Escurrí. Hacelo a fuego fuerte y sin tapa.', 3, 'Fuego fuerte', 'Destapado'),
  (85, 2, 'Relleno', 'Rehogá la cebolla picada y mezclala con el brócoli, los huevos batidos con la crema, sal y pimienta y la muzzarella en cubos. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (85, 3, 'Hornear', 'Volcá sobre la masa en la tartera, espolvoreá queso rallado y horneá a 190 °C 30 minutos.', 30, 'Horno 190 °C', NULL),
  (86, 1, 'Salsa', 'Cubrí la prepizza con el puré de tomate condimentado con sal y orégano y horneá a 220 °C 8 minutos.', 8, 'Horno 220 °C', NULL),
  (86, 2, 'Queso', 'Agregá la muzzarella en cubos y las rodajas de tomate. Volvé al horno 8 minutos. Horno a 220 °C.', 8, 'Horno 220 °C', NULL),
  (86, 3, 'Terminar', 'Sacala y cubrí con ajo picado mezclado con aceite, orégano y aceitunas.', NULL, NULL, NULL),
  (87, 1, 'Prehornear', 'Cubrí la prepizza con la salsa y horneá a 220 °C 8 minutos.', 8, 'Horno 220 °C', NULL),
  (87, 2, 'Cubrir', 'Agregá la muzzarella, el jamón en tiras y el morrón en tiras finas.', NULL, NULL, NULL),
  (87, 3, 'Gratinar', 'Horneá 8 a 10 minutos más y terminá con orégano y aceitunas. Horno a 220 °C.', 10, 'Horno 220 °C', NULL),
  (88, 1, 'Base', 'Cubrí la prepizza con la salsa y horneá a 220 °C 8 minutos.', 8, 'Horno 220 °C', NULL),
  (88, 2, 'Queso', 'Agregá la muzzarella y horneá 8 minutos más. Horno a 220 °C.', 8, 'Horno 220 °C', NULL),
  (88, 3, 'Terminar', 'Cubrí con la rúcula, el jamón crudo, queso rallado y un hilo de aceite de oliva.', NULL, NULL, NULL),
  (89, 1, 'Mezcla', 'Batí la harina de garbanzo con 750 ml de agua, sal y pimienta hasta que no queden grumos. Dejá reposar 30 minutos.', 30, NULL, NULL),
  (89, 2, 'Pizzera caliente', 'Precalentá el horno a 250 °C con una pizzera con el aceite adentro durante 5 minutos.', 5, 'Horno 250 °C', NULL),
  (89, 3, 'Hornear', 'Volcá la mezcla sobre el aceite caliente y horneá 20 a 25 minutos hasta que esté dorada. Si querés, espolvoreá queso rallado. Horno a 250 °C.', 25, 'Horno 250 °C', NULL),
  (90, 1, 'Dorar', 'Salpimentá las presas y dorálas en una cacerola con aceite. Retirá. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (90, 2, 'Sofrito', 'Rehogá cebolla, morrón y ajo 8 minutos. Sumá pimentón y mostaza. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (90, 3, 'Cocinar', 'Volvé el pollo, agregá la cerveza y las papas en cubos. Tapá y cociná a fuego bajo 40 minutos.', 40, 'Fuego bajo', 'Tapado'),
  (90, 4, 'Reducir', 'Destapá y cociná 10 minutos más para que espese la salsa. Hacelo a fuego medio.', 10, 'Fuego medio', 'Destapado'),
  (91, 1, 'Arroz', 'Hervé el arroz en agua con sal 15 minutos y reservá. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 15, 'Fuerte, después medio', 'Destapado'),
  (91, 2, 'Base', 'Rehogá la cebolla, el ajo y el jengibre picados 6 minutos. Sumá el curry y revolvé 1 minuto. Hacelo a fuego medio y sin tapa.', 7, 'Fuego medio', 'Destapado'),
  (91, 3, 'Pollo', 'Agregá la pechuga en cubos y cociná hasta que esté blanca por fuera. Hacelo a fuego medio-fuerte y sin tapa.', 6, 'Fuego medio-fuerte', 'Destapado'),
  (91, 4, 'Salsa', 'Incorporá la leche de coco (o la crema), salá y cociná 10 minutos a fuego bajo. Serví con el arroz. Sin tapa.', 10, 'Fuego bajo', 'Destapado'),
  (92, 1, 'Cortar', 'Cortá el pollo en tiras y todas las verduras en bastones finos.', NULL, NULL, NULL),
  (92, 2, 'Pollo', 'Calentá el wok o una sartén grande con aceite a fuego fuerte y dorá el pollo 5 minutos. Retirá. Sin tapa.', 5, 'Fuego fuerte', 'Destapado'),
  (92, 3, 'Verduras', 'Salteá las verduras con ajo y jengibre 4 minutos, moviendo todo el tiempo. Hacelo a fuego fuerte y sin tapa.', 4, 'Fuego fuerte', 'Destapado'),
  (92, 4, 'Unir', 'Volvé el pollo, agregá la salsa de soja y salteá 1 minuto. Terminá con sésamo o maní y serví con arroz. Hacelo a fuego fuerte y sin tapa.', 1, 'Fuego fuerte', 'Destapado'),
  (93, 1, 'Empanar', 'Abrí las pechugas en supremas, pasalas por huevo batido con sal y por pan rallado.', NULL, NULL, NULL),
  (93, 2, 'Cocinar', 'Horneá a 200 °C 12 minutos por lado.', 24, 'Horno 200 °C', NULL),
  (93, 3, 'Cubrir', 'Poné salsa, jamón y muzzarella sobre cada suprema.', NULL, NULL, NULL),
  (93, 4, 'Gratinar', 'Horneá a 220 °C 8 minutos hasta que el queso se derrita. Terminá con orégano.', 8, 'Horno 220 °C', NULL),
  (94, 1, 'Pollo', 'Dorá la pechuga en cubos en una sartén con aceite. Retirá. Hacelo a fuego fuerte y sin tapa.', 6, 'Fuego fuerte', 'Destapado'),
  (94, 2, 'Champiñones', 'Derretí la manteca, rehogá la cebolla y el ajo y sumá los champiñones fileteados hasta que se doren. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (94, 3, 'Salsa', 'Agregá el vino y dejá evaporar. Sumá la crema y el pollo y cociná 5 minutos. Serví con arroz o puré. Hacelo a fuego bajo y sin tapa.', 7, 'Fuego bajo', 'Destapado'),
  (95, 1, 'Condimentar', 'Secá las alitas y mezclalas con aceite, sal, pimienta, pimentón y ajo en polvo.', NULL, NULL, NULL),
  (95, 2, 'Hornear', 'Acomodalas en una placa y horneá a 220 °C 35 minutos, dándolas vuelta a mitad de cocción.', 35, 'Horno 220 °C', NULL),
  (95, 3, 'Glasear', 'Pincelalas con la salsa barbacoa (o miel con soja) y horneá 8 minutos más. Horno a 220 °C.', 8, 'Horno 220 °C', NULL),
  (96, 1, 'Arroz', 'Hervé el arroz 15 minutos y reservá. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 15, 'Fuerte, después medio', 'Destapado'),
  (96, 2, 'Salsa', 'Mezclá 150 ml del almíbar del ananá con la soja, el vinagre, el kétchup y la fécula.', NULL, NULL, NULL),
  (96, 3, 'Saltear', 'Dorá la pechuga en cubos con aceite. Sumá la cebolla y los morrones en cubos y salteá 4 minutos. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (96, 4, 'Terminar', 'Agregá el ananá en cubos y la salsa; cociná hasta que espese y brille. Serví con el arroz. Hacelo a fuego medio y sin tapa.', 3, 'Fuego medio', 'Destapado'),
  (97, 1, 'Condimentar', 'Cortá el pollo en tiras y condimentalo con comino, pimentón, sal y jugo de lima.', NULL, NULL, NULL),
  (97, 2, 'Saltear', 'Dorá el pollo en una sartén bien caliente con aceite. Sumá los morrones y la cebolla en tiras y cociná 5 minutos. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (97, 3, 'Servir', 'Calentá las tortillas y serví con el relleno, palta pisada y tomate picado. Hacelo a fuego medio.', NULL, 'Fuego medio', NULL),
  (98, 1, 'Dorar', 'Salpimentá las presas y dorálas en una sartén grande con aceite 10 minutos de cada lado. Hacelo a fuego medio-fuerte y sin tapa.', 20, 'Fuego medio-fuerte', 'Destapado');
INSERT INTO "RecetaPasos" ("RecetaId", "Numero", "Titulo", "Descripcion", "Minutos", "Fuego", "Tapa") VALUES
  (98, 2, 'Ajo', 'Bajá el fuego y sumá los ajos laminados. Cociná 2 minutos sin que se quemen. Hacelo a fuego bajo y sin tapa.', 2, 'Fuego bajo', 'Destapado'),
  (98, 3, 'Vino', 'Agregá el vino, tapá y cociná 20 minutos. Terminá con perejil picado. Hacelo a fuego bajo.', 20, 'Fuego bajo', 'Tapado'),
  (99, 1, 'Verduras', 'Cortá el zucchini en rodajas, mezclalo con los tomates cherry, ajo, aceite y sal, y horneá a 200 °C 10 minutos.', 10, 'Horno 200 °C', NULL),
  (99, 2, 'Salmón', 'Apoyá el salmón sobre las verduras, salpimentalo y cubrilo con rodajas de limón.', NULL, NULL, NULL),
  (99, 3, 'Hornear', 'Horneá 12 a 15 minutos, hasta que esté cocido pero jugoso. Horno a 200 °C.', 15, 'Horno 200 °C', NULL),
  (100, 1, 'Ajo', 'Calentá el aceite de oliva a fuego medio con el ajo laminado y el ají, 1 minuto. Sin tapa.', 1, 'Fuego medio', 'Destapado'),
  (100, 2, 'Langostinos', 'Subí el fuego, agregá los langostinos pelados y salteá 2 o 3 minutos hasta que estén rosados. Hacelo a fuego fuerte y sin tapa.', 3, 'Fuego fuerte', 'Destapado'),
  (100, 3, 'Servir', 'Salá, sumá perejil y limón y serví con pan para mojar en el aceite.', NULL, NULL, NULL),
  (101, 1, 'Preparar', 'Cortá los calamares en anillos, secalos y pasalos por leche (opcional, quedan más tiernos).', NULL, NULL, NULL),
  (101, 2, 'Rebozar', 'Escurrilos y pasalos por harina con sal, sacudiendo el exceso.', NULL, NULL, NULL),
  (101, 3, 'Freír', 'Freílos en aceite muy caliente 2 minutos, hasta que estén dorados. Escurrí y serví con limón. Hacelo a fuego fuerte y sin tapa.', 6, 'Fuego fuerte', 'Destapado'),
  (102, 1, 'Pollo', 'Dorá las presas de pollo en una paellera o sartén grande con aceite. Reservá. Hacelo a fuego fuerte y sin tapa.', 15, 'Fuego fuerte', 'Destapado'),
  (102, 2, 'Sofrito', 'Rehogá cebolla, morrón y ajo picados 8 minutos. Sumá el tomate rallado, el pimentón y el calamar en anillos. Hacelo a fuego medio y sin tapa.', 12, 'Fuego medio', 'Destapado'),
  (102, 3, 'Arroz', 'Agregá el arroz y revolvé 2 minutos. Volcá 1 litro de caldo caliente con el azafrán y acomodá el pollo. Hacelo a fuego fuerte y sin tapa.', 2, 'Fuego fuerte', 'Destapado'),
  (102, 4, 'Cocinar', 'Cociná a fuego medio 12 minutos sin revolver. Sumá los langostinos, los mejillones y las arvejas y cociná 8 minutos más. Sin tapa.', 20, 'Fuego medio', 'Destapado'),
  (102, 5, 'Reposar', 'Apagá, tapá con un repasador 5 minutos y serví con gajos de limón.', 5, 'Fuera del fuego', 'Tapado'),
  (103, 1, 'Papas', 'Cortá las papas en rodajas finas y la cebolla en aros. Acomodalas en una fuente con aceite y sal y horneá a 200 °C 25 minutos.', 25, 'Horno 200 °C', NULL),
  (103, 2, 'Pescado', 'Poné los filets encima, salpimentá, rociá con limón, vino, ajo picado y pimentón.', NULL, NULL, NULL),
  (103, 3, 'Hornear', 'Horneá 12 minutos más y terminá con perejil. Horno a 200 °C.', 12, 'Horno 200 °C', NULL),
  (104, 1, 'Preparar', 'Secá la trucha, salpimentala y pasala apenas por harina.', NULL, NULL, NULL),
  (104, 2, 'Dorar', 'Derretí la mitad de la manteca y cociná la trucha con la piel hacia abajo 4 minutos, dalo vuelta y cociná 2 minutos más. Hacelo a fuego medio y sin tapa.', 6, 'Fuego medio', 'Destapado'),
  (104, 3, 'Salsa', 'Retirá, sumá el resto de la manteca, el jugo de limón y las alcaparras, y bañá el pescado. Hacelo a fuego medio y sin tapa.', 1, 'Fuego medio', 'Destapado'),
  (105, 1, 'Puré', 'Hervé las papas 20 minutos, pisalas y dejalas entibiar. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 20, 'Fuerte, después medio', 'Destapado'),
  (105, 2, 'Mezcla', 'Uní el puré con el atún escurrido, un huevo, cebolla y perejil picados, sal y pimienta. Enfriá 30 minutos.', 30, NULL, NULL),
  (105, 3, 'Formar', 'Formá croquetas, pasalas por el otro huevo batido y por pan rallado.', NULL, NULL, NULL),
  (105, 4, 'Cocinar', 'Freílas en aceite caliente o horneálas a 200 °C 20 minutos. Hacelo a fuego medio-fuerte y sin tapa.', 20, 'Fuego medio-fuerte', 'Destapado'),
  (106, 1, 'Limpiar', 'Lavá los mejillones con un cepillo y sacales las barbas.', NULL, NULL, NULL),
  (106, 2, 'Base', 'Derretí la manteca en una olla grande con el ajo picado 1 minuto. Hacelo a fuego medio y sin tapa.', 1, 'Fuego medio', 'Destapado'),
  (106, 3, 'Al vapor', 'Agregá los mejillones y el vino, tapá y cociná 5 minutos a fuego fuerte, sacudiendo la olla, hasta que se abran.', 5, 'Fuego fuerte', 'Tapado'),
  (106, 4, 'Servir', 'Terminá con perejil picado y limón. Serví con el caldo y pan.', NULL, NULL, NULL),
  (107, 1, 'Fideos', 'Hervé los fideos en abundante agua con sal. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (107, 2, 'Salsa', 'Rehogá el ajo en aceite 1 minuto, sumá el tomate y cociná 8 minutos. Agregá aceitunas, alcaparras y ají. Hacelo a fuego medio y sin tapa.', 9, 'Fuego medio', 'Destapado'),
  (107, 3, 'Unir', 'Incorporá el atún escurrido, mezclá con los fideos y terminá con perejil. Fuera del fuego.', NULL, 'Fuera del fuego', NULL),
  (108, 1, 'Tuco', 'Rehogá la cebolla y el ajo 8 minutos (sumá la carne si usás). Agregá el puré, laurel, orégano y sal y cociná 20 minutos. Hacelo a fuego bajo, con la tapa apenas corrida.', 28, 'Fuego bajo', 'Semitapado'),
  (108, 2, 'Ravioles', 'Hervé los ravioles en abundante agua con sal el tiempo que indique el paquete. Hacelo a fuego medio y sin tapa.', 6, 'Fuego medio', 'Destapado'),
  (108, 3, 'Servir', 'Escurrilos con cuidado y serví con el tuco y queso rallado.', NULL, NULL, NULL),
  (109, 1, 'Salsa', 'Rehogá la cebolla y el ajo 8 minutos, sumá el puré y cociná 15 minutos. Agregá la crema y calentá sin hervir. Hacelo a fuego bajo, con la tapa apenas corrida.', 23, 'Fuego bajo', 'Semitapado'),
  (109, 2, 'Sorrentinos', 'Hervilos en agua con sal según el paquete. Hacelo a fuego medio y sin tapa.', 7, 'Fuego medio', 'Destapado'),
  (109, 3, 'Servir', 'Serví con la salsa y queso rallado.', NULL, NULL, NULL),
  (110, 1, 'Bolognesa', 'Rehogá cebolla y zanahoria picadas, sumá la carne y dorala. Agregá el puré y cociná 20 minutos. Hacelo a fuego bajo, con la olla tapada.', 30, 'Fuego bajo', 'Tapado'),
  (110, 2, 'Salsa blanca', 'Derretí la manteca, sumá la harina, revolvé y agregá la leche de a poco hasta que espese. Condimentá con sal y nuez moscada. Hacelo a fuego medio-bajo y sin tapa.', 10, 'Fuego medio-bajo', 'Destapado'),
  (110, 3, 'Armar', 'En una fuente alterná capas de bolognesa, láminas de pasta, salsa blanca y muzzarella. Terminá con salsa blanca y queso rallado.', NULL, NULL, NULL),
  (110, 4, 'Hornear', 'Horneá a 180 °C 40 minutos (si las láminas son secas, revisá el paquete). Dejá reposar 10 minutos.', 40, 'Horno 180 °C', NULL),
  (111, 1, 'Verdura', 'Cociná la verdura, escurrila muy bien y picala. Rehogá la cebolla y mezclá con la verdura, la ricota, el huevo, sal y nuez moscada. Hacelo a fuego medio y sin tapa.', 15, 'Fuego medio', 'Destapado'),
  (111, 2, 'Salsa blanca', 'Hacé una salsa blanca con la manteca, la harina y la leche. Hacelo a fuego medio-bajo y sin tapa.', 10, 'Fuego medio-bajo', 'Destapado'),
  (111, 3, 'Armar', 'Alterná capas de pasta, relleno, salsa blanca y muzzarella. Si querés, sumá un poco de tuco entre capas.', NULL, NULL, NULL),
  (111, 4, 'Hornear', 'Cubrí con salsa blanca y queso rallado y horneá a 180 °C 40 minutos.', 40, 'Horno 180 °C', NULL),
  (112, 1, 'Pesto', 'Procesá o picá muy fino las hojas de albahaca con el ajo, las nueces, el queso, el aceite y sal hasta lograr una pasta.', NULL, NULL, NULL),
  (112, 2, 'Pasta', 'Hervé los tallarines en agua con sal. Reservá medio cucharón del agua. Hacelo a fuego fuerte y sin tapa.', 4, 'Fuego fuerte', 'Destapado'),
  (112, 3, 'Unir', 'Mezclá la pasta con el pesto y un poco del agua de cocción para que quede cremoso. Fuera del fuego.', NULL, 'Fuera del fuego', NULL),
  (113, 1, 'Sofrito', 'Rehogá cebolla, zanahoria, morrón y ajo picados 10 minutos. Hacelo a fuego medio y sin tapa.', 10, 'Fuego medio', 'Destapado'),
  (113, 2, 'Carne', 'Sumá la carne y dorala. Agregá el vino y dejá evaporar. Hacelo a fuego medio-fuerte y sin tapa.', 10, 'Fuego medio-fuerte', 'Destapado'),
  (113, 3, 'Salsa', 'Incorporá el puré y el laurel y cociná tapado a fuego bajo 30 minutos.', 30, 'Fuego bajo', 'Tapado'),
  (113, 4, 'Servir', 'Hervé los fideos y serví con la salsa y queso rallado. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (114, 1, 'Fideos', 'Hervé los fideos en agua con sal. Reservá una taza del agua de cocción. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (114, 2, 'Panceta', 'Dorá la panceta en cubos en una sartén sin aceite hasta que esté crocante. Hacelo a fuego medio y sin tapa.', 6, 'Fuego medio', 'Destapado'),
  (114, 3, 'Crema de huevo', 'Batí los huevos con el queso rallado y mucha pimienta.', NULL, NULL, NULL),
  (114, 4, 'Unir', 'Fuera del fuego mezclá los fideos con la panceta y la mezcla de huevo, sumando agua de cocción hasta que quede cremoso.', NULL, 'Fuera del fuego', NULL),
  (115, 1, 'Hervir', 'Hervé los fideos y sumá el brócoli en ramitos en los últimos 3 minutos. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (115, 2, 'Ajo', 'Dorá el ajo laminado en el aceite de oliva con el ají, a fuego bajo. Sin tapa.', 2, 'Fuego bajo', 'Destapado'),
  (115, 3, 'Unir', 'Escurrí, mezclá con el aceite de ajo y terminá con queso rallado. Fuera del fuego.', NULL, 'Fuera del fuego', NULL),
  (116, 1, 'Salsa', 'Calentá la crema a fuego bajo y sumá los quesos en trozos, revolviendo hasta que se derritan. Condimentá con nuez moscada y pimienta. Sin tapa.', 8, 'Fuego bajo', 'Destapado'),
  (116, 2, 'Ñoquis', 'Hervé los ñoquis en agua con sal; cuando suben, están listos. Hacelo a fuego medio y sin tapa.', 4, 'Fuego medio', 'Destapado'),
  (116, 3, 'Servir', 'Escurrilos y mezclalos con la salsa.', NULL, NULL, NULL),
  (117, 1, 'Hidratar', 'Si usás hongos secos, remojalos en 200 ml de agua caliente 15 minutos.', 15, NULL, NULL),
  (117, 2, 'Salsa', 'Rehogá cebolla y ajo en manteca, sumá los champiñones fileteados y los hongos picados. Agregá el vino, el agua de los hongos y la crema; cociná 8 minutos. Hacelo a fuego medio y sin tapa.', 15, 'Fuego medio', 'Destapado'),
  (117, 3, 'Servir', 'Mezclá con los fideos hervidos y queso rallado. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (118, 1, 'Caldo', 'Disolvé el caldo en 1,2 litros de agua caliente (sumá el agua de los hongos secos hidratados).', NULL, NULL, NULL),
  (118, 2, 'Base', 'Rehogá la cebolla en la mitad de la manteca, sumá los hongos y dorá 5 minutos. Agregá el arroz y nacaralo 2 minutos. Hacelo a fuego medio y sin tapa.', 7, 'Fuego medio', 'Destapado'),
  (118, 3, 'Cocción', 'Agregá el vino y dejá evaporar. Sumá el caldo de a un cucharón, revolviendo, durante 18 minutos. Hacelo a fuego medio y sin tapa.', 18, 'Fuego medio', 'Destapado'),
  (118, 4, 'Mantecar', 'Fuera del fuego agregá el resto de la manteca y el queso. Tapá 2 minutos y serví.', 2, 'Fuera del fuego', 'Tapado'),
  (119, 1, 'Base', 'Rehogá la cebolla en manteca, sumá la calabaza en cubitos y cociná 5 minutos. Agregá el arroz y revolvé 2 minutos. Hacelo a fuego medio y sin tapa.', 7, 'Fuego medio', 'Destapado'),
  (119, 2, 'Cocción', 'Agregá el vino y luego el caldo caliente de a un cucharón, revolviendo, durante 18 minutos. Hacelo a fuego medio y sin tapa.', 18, 'Fuego medio', 'Destapado'),
  (119, 3, 'Mantecar', 'Fuera del fuego sumá manteca, queso y nuez moscada.', NULL, 'Fuera del fuego', NULL),
  (120, 1, 'Porotos', 'Hervé los porotos remojados 45 minutos. Hacelo a fuego bajo, con la tapa apenas corrida.', 45, 'Fuego bajo', 'Semitapado'),
  (120, 2, 'Sofrito', 'Dorá el chorizo y la panceta. Sumá cebolla, morrón y ajo y rehogá 8 minutos. Agregá el pimentón. Hacelo a fuego medio y sin tapa.', 15, 'Fuego medio', 'Destapado'),
  (120, 3, 'Guisar', 'Incorporá los porotos, el zapallo en cubos, el puré, el caldo, el laurel y agua hasta cubrir. Cociná 30 minutos. Hacelo a fuego bajo, con la olla tapada.', 30, 'Fuego bajo', 'Tapado'),
  (121, 1, 'Rehogar', 'Rehogá la cebolla en aceite 5 minutos. Hacelo a fuego medio y sin tapa.', 5, 'Fuego medio', 'Destapado'),
  (121, 2, 'Hervir', 'Sumá la calabaza y la papa en cubos, el jengibre y el caldo con 1 litro de agua. Cociná 25 minutos. Hacelo a fuego medio, con la olla tapada.', 25, 'Fuego medio', 'Tapado'),
  (121, 3, 'Licuar', 'Licuá hasta que quede liso. Ajustá sal, nuez moscada y sumá la crema.', NULL, NULL, NULL),
  (122, 1, 'Base', 'Dorá la panceta y sumá cebolla y zanahoria picadas 8 minutos. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (122, 2, 'Cocinar', 'Agregá las arvejas, la papa, el laurel y el caldo con 1,5 litros de agua. Cociná 50 minutos, revolviendo cada tanto. Hacelo a fuego bajo, con la tapa apenas corrida.', 50, 'Fuego bajo', 'Semitapado'),
  (122, 3, 'Terminar', 'Pisá un poco o licuá la mitad para que espese. Ajustá la sal.', NULL, NULL, NULL),
  (123, 1, 'Caramelizar', 'Cociná las cebollas en pluma en la manteca a fuego bajo 30 minutos, revolviendo, hasta que estén bien doradas. Sin tapa.', 30, 'Fuego bajo', 'Destapado'),
  (123, 2, 'Caldo', 'Sumá la harina, el vino y el caldo con 1,2 litros de agua. Cociná 15 minutos. Hacelo a fuego medio y sin tapa.', 15, 'Fuego medio', 'Destapado'),
  (123, 3, 'Gratinar', 'Serví en cazuelas, cubrí con rodajas de pan tostado y queso, y gratiná en el horno fuerte 5 minutos. Horno a 220 °C.', 5, 'Horno 220 °C', NULL),
  (124, 1, 'Porotos', 'Hervé los porotos remojados con laurel durante 1 hora. Hacelo a fuego bajo, con la tapa apenas corrida.', 60, 'Fuego bajo', 'Semitapado'),
  (124, 2, 'Sofrito', 'Dorá la panceta y el chorizo, sumá cebolla y ajo y rehogá. Agregá a los porotos con comino y cociná 20 minutos más. Hacelo a fuego medio y sin tapa.', 25, 'Fuego medio', 'Destapado'),
  (124, 3, 'Arroz', 'Hervé el arroz 15 minutos y serví junto a los porotos, con gajos de naranja si te gusta. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 15, 'Fuerte, después medio', 'Destapado'),
  (125, 1, 'Caldo', 'Poné el pollo en 2 litros de agua fría con sal y llevá a hervor. Retirá la espuma. Hacelo a fuego fuerte y sin tapa.', 10, 'Fuego fuerte', 'Destapado'),
  (125, 2, 'Verduras', 'Sumá las verduras en trozos y cociná 40 minutos a fuego bajo. Con la tapa apenas corrida.', 40, 'Fuego bajo', 'Semitapado'),
  (125, 3, 'Fideos', 'Retirá el pollo, desmenuzalo y volvelo a la olla. Agregá los fideos y cociná 5 minutos. Hacelo a fuego medio y sin tapa.', 5, 'Fuego medio', 'Destapado'),
  (126, 1, 'Coliflor', 'Separá en ramitos y hervila 8 minutos. Escurrí. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 8, 'Fuerte, después medio', 'Destapado'),
  (126, 2, 'Salsa blanca', 'Derretí la manteca, sumá la harina y la leche de a poco hasta que espese. Condimentá. Hacelo a fuego medio-bajo y sin tapa.', 10, 'Fuego medio-bajo', 'Destapado'),
  (126, 3, 'Gratinar', 'Poné la coliflor en una fuente, cubrí con la salsa y el queso y horneá a 220 °C 20 minutos.', 20, 'Horno 220 °C', NULL),
  (127, 1, 'Asar', 'Cortá las berenjenas a lo largo, hacé cortes en la pulpa, salá, rociá con aceite y horneá a 200 °C 25 minutos.', 25, 'Horno 200 °C', NULL),
  (127, 2, 'Relleno', 'Retirá la pulpa y picala. Rehogá cebolla, morrón, ajo y tomate, sumá la pulpa (y la carne si usás) y cociná 10 minutos. Hacelo a fuego medio y sin tapa.', 15, 'Fuego medio', 'Destapado'),
  (127, 3, 'Gratinar', 'Rellená las berenjenas, cubrí con muzzarella y pan rallado y horneá 15 minutos. Horno a 200 °C.', 15, 'Horno 200 °C', NULL),
  (128, 1, 'Arroz', 'Hervé el arroz 12 minutos y escurrilo. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 12, 'Fuerte, después medio', 'Destapado'),
  (128, 2, 'Relleno', 'Rehogá la cebolla y el tomate, sumá la carne y cociná. Mezclá con el arroz, pimentón y la mitad del queso. Hacelo a fuego medio y sin tapa.', 15, 'Fuego medio', 'Destapado');
INSERT INTO "RecetaPasos" ("RecetaId", "Numero", "Titulo", "Descripcion", "Minutos", "Fuego", "Tapa") VALUES
  (128, 3, 'Hornear', 'Cortá la tapa de los morrones, retirá las semillas y rellenalos. Cubrí con queso y horneá a 190 °C 30 minutos.', 30, 'Horno 190 °C', NULL),
  (129, 1, 'Arroz y huevos', 'Hervé el arroz 15 minutos y los huevos 10 minutos. Enfriá. Hacelo a fuego fuerte hasta que hierva y después a fuego medio, sin tapa.', 15, 'Fuerte, después medio', 'Destapado'),
  (129, 2, 'Vaciar', 'Cortá una tapa a cada tomate, vacialos con una cuchara y salá el interior.', NULL, NULL, NULL),
  (129, 3, 'Relleno', 'Mezclá el atún, el arroz, el huevo picado, el choclo y la mayonesa.', NULL, NULL, NULL),
  (129, 4, 'Servir', 'Rellená los tomates y serví fríos sobre hojas de lechuga.', NULL, NULL, NULL),
  (130, 1, 'Cortar', 'Pelá las papas y cortalas en rodajas muy finas.', NULL, NULL, NULL),
  (130, 2, 'Crema', 'Calentá la crema con la leche, el ajo, sal, pimienta y nuez moscada. Hacelo a fuego bajo y sin tapa.', 5, 'Fuego bajo', 'Destapado'),
  (130, 3, 'Armar', 'En una fuente enmantecada acomodá las papas en capas y cubrí con la crema caliente y el queso.', NULL, NULL, NULL),
  (130, 4, 'Hornear', 'Horneá a 180 °C 50 minutos, hasta que estén tiernas y doradas.', 50, 'Horno 180 °C', NULL),
  (131, 1, 'Huevo', 'Revolvé los huevos en un wok o sartén grande con aceite. Retirá. Hacelo a fuego medio y sin tapa.', 2, 'Fuego medio', 'Destapado'),
  (131, 2, 'Verduras', 'Salteá la zanahoria en cubitos, el verdeo y las arvejas 3 minutos a fuego fuerte. Sin tapa.', 3, 'Fuego fuerte', 'Destapado'),
  (131, 3, 'Arroz', 'Sumá el arroz, el jamón y la salsa de soja y salteá 4 minutos. Volvé el huevo y mezclá. Hacelo a fuego fuerte y sin tapa.', 4, 'Fuego fuerte', 'Destapado'),
  (132, 1, 'Quinoa', 'Lavá la quinoa y hervila en el doble de agua con sal 15 minutos. Hacelo a fuego bajo, con la olla tapada.', 15, 'Fuego bajo', 'Tapado'),
  (132, 2, 'Verduras', 'Salteá las verduras en cubos con aceite 8 minutos. Hacelo a fuego medio-fuerte y sin tapa.', 8, 'Fuego medio-fuerte', 'Destapado'),
  (132, 3, 'Unir', 'Mezclá con la quinoa, condimentá con soja y, si querés, sumá un huevo revuelto.', NULL, NULL, NULL),
  (133, 1, 'Cuscús', 'Disolvé el caldo en 250 ml de agua hirviendo, volcalo sobre el cuscús, tapá 5 minutos y desgraná con un tenedor. Fuera del fuego.', 5, 'Fuera del fuego', 'Tapado'),
  (133, 2, 'Verduras', 'Salteá la cebolla, el zucchini y el morrón en cubos con comino y cúrcuma 8 minutos. Sumá los garbanzos. Hacelo a fuego medio y sin tapa.', 10, 'Fuego medio', 'Destapado'),
  (133, 3, 'Unir', 'Mezclá con el cuscús y las pasas. Ajustá la sal.', NULL, NULL, NULL),
  (134, 1, 'Chauchas', 'Cortales las puntas y hervilas 6 minutos. Escurrí. Hacelo a fuego fuerte y sin tapa.', 6, 'Fuego fuerte', 'Destapado'),
  (134, 2, 'Saltear', 'Rehogá la cebolla y el ajo, sumá las chauchas y salteá 3 minutos. Hacelo a fuego medio y sin tapa.', 8, 'Fuego medio', 'Destapado'),
  (134, 3, 'Huevo', 'Agregá los huevos batidos con queso y revolvé hasta que cuajen. Hacelo a fuego bajo y sin tapa.', 2, 'Fuego bajo', 'Destapado'),
  (135, 1, 'Batir', 'Batí los huevos con sal y pimienta.', NULL, NULL, NULL),
  (135, 2, 'Cocinar', 'Derretí la manteca en una sartén, volcá los huevos y mové los bordes hacia el centro hasta que estén casi cuajados. Hacelo a fuego medio-bajo y sin tapa.', 3, 'Fuego medio-bajo', 'Destapado'),
  (135, 3, 'Rellenar', 'Poné el jamón y el queso en una mitad, doblá y cociná 1 minuto más. Hacelo a fuego bajo.', 1, 'Fuego bajo', NULL),
  (136, 1, 'Hervir', 'Hervé las remolachas con cáscara 40 minutos y los huevos 10 minutos. Hacelo a fuego medio, con la tapa apenas corrida.', 40, 'Fuego medio', 'Semitapado'),
  (136, 2, 'Cortar', 'Pelá las remolachas y cortalas en cubos; picá los huevos y la cebolla.', NULL, NULL, NULL),
  (136, 3, 'Condimentar', 'Mezclá todo con aceite, vinagre y sal.', NULL, NULL, NULL),
